window.STOTT = window.STOTT || {};
window.STOTT.apparatus = window.STOTT.apparatus || {};
window.STOTT.apparatus.reformer = {
  essential: [
    { name: "Footwork", level: "Essential", page: "22–27", springs: "3–4", startingPosition: "Supine, pelvis and spine neutral, footbar position #1, headrest adjusted for the individual.\nArms long by the sides of the body, palms down — this base position, plus the shared Focus criteria below, carries through Second Position and Single Leg too.\nFoot/leg placement is specific to each of the five positions below.", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale to bend the knees in\nExhale to press the carriage out — one breath per position, worked through in sequence.", targetMuscles: "Quadriceps, gluteus maximus, calves, deep hip stabilizers.", focus: "The very first Reformer exercise — establishes neutral pelvis/spine under load and warms up the whole leg through five foot positions.\nShares its full Focus checklist (p.22: neutral pelvis/lumbar, stable ribcage/scapulae, full leg extension without locking, hip-knee-ankle alignment, vasti tracking the patella, level pelvis) with Second Position and Single Leg\nEach position below adds its own extra focus point on top of that shared list.", positions: [
      { label: "Toes apart, heels together", detail: "Balls of the feet on the footbar, toes apart, heels together. Legs laterally rotated, knees flexed just wider than shoulder-distance apart, knees pointing over the center of the feet." },
      { label: "Wrap toes on bar", detail: "Distal ends of the metatarsals on the footbar, toes gently flexed around the bar without clenching. Legs parallel and adducted, knees flexed." },
      { label: "Heels on bar", detail: "Heels on the footbar, ankles dorsiflexed. Legs parallel and adducted, knees flexed." },
      { label: "High half-toe", detail: "Balls of the feet on the footbar, ankles plantar flexed. Legs parallel and adducted, knees flexed." },
      { label: "Lower & lift", detail: "Same start as High Half-Toe — balls of the feet on the footbar, ankles plantar flexed, legs parallel and adducted, knees flexed. Once extended, heels lower under the bar (dorsiflex) then lift again (plantar flex) before the carriage returns." },
    ], faults: ["Pelvis rocking as the carriage moves — keep the ASIS level throughout.", "Knees splaying — track them over the 2nd/3rd toes."], modifications: ["Alternate breath (1-4).", "Small range pulse (1-4).", "End range pulse (1-4).", "Feet slightly abducted (2-5).", "Use a spacer."] , script: { lines: ["Let's move into Footwork. Come to supine, headrest set, balls of your feet on the bar, hip-distance apart.", "Exhale to press the carriage out; inhale to bend your knees back in. We'll move through five foot positions in sequence — toes apart heels together, wrapped toes, heels on the bar, high half-toe, then lower and lift.", "Press through your whole foot, not just your toes — feel your quadriceps and glutes doing the work of the press while your deep hip stabilizers keep your pelvis level and still, not rocking as the carriage moves."] } },
    { name: "Second Position", level: "Essential", page: "28–29", springs: "3–4", startingPosition: "Supine, pelvis and spine neutral, footbar #1, headrest adjusted for the individual.\nHeels on the footbar throughout — rotation and heel width vary by position below (this differs from Footwork's balls-of-feet start and from Single Leg's one-foot base).", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale in\nExhale to press out.", targetMuscles: "Adductors/abductors depending on rotation, quadriceps, glutes.", focus: "Repeats the Footwork press through three leg rotations to train the hips through different planes.\nShares the same Focus checklist from page 22 as Footwork and Single Leg, plus its own emphasis on keeping the knees aligned over the feet through the lateral/medial rotation.", positions: [
      { label: "Parallel, hip-distance", detail: "Heels on the footbar, ankles dorsiflexed. Legs parallel and abducted, hip-distance apart." },
      { label: "Laterally rotated (V, wide)", detail: "Heels as wide as possible on the footbar, ankles dorsiflexed. Legs laterally rotated, knees flexed and pointing over the center of the feet." },
      { label: "Medially rotated", detail: "Heels on the footbar, abducted slightly wider than hip-distance apart. Legs medially rotated, knees flexed and touching." },
    ], modifications: ["Alternate breath (1-3).", "Small range pulse (1-3).", "End range pulse (1-3).", "Flex-Band around the thigh."] , script: { lines: ["Let's move into Second Position. Come to supine, headrest set, heels on the bar throughout.", "Exhale to press the carriage out; inhale to bend your knees back in. We'll work through three leg rotations — parallel, turned out wide, then turned in.", "Keep your knees tracking directly over your feet through each rotation, and your pelvis completely still — notice your inner and outer thighs, the adductors and abductors, sharing more of the load as the rotation changes, alongside your quadriceps and glutes."] } },
    { name: "Single Leg", level: "Essential", page: "30–32", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral, footbar #1, headrest adjusted for the individual.\nOne leg supports on the footbar (ball of the foot or heel, aligned with the sit-bone) while the other gestures — exact placement of both legs varies by position below (again different from Footwork's two-feet start and Second Position's heels-on-bar start).", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale to extend the supporting knee, pressing the carriage out\nExhale to flex the supporting knee and hip, controlling the return of the carriage — reversed from Footwork's breath, since the second leg is no longer there to help stabilize.", targetMuscles: "Unilateral hip extensors and quadriceps of the supporting leg concentrically on the press, eccentrically on the return; hip flexors and quadriceps of the gesture leg holding isometrically; deep core (anti-rotation while one leg works).", focus: "Removes the second leg's support to test single-leg control and pelvic stability.\nShares the same Focus checklist from page 22 as Footwork and Second Position, plus its own emphasis on matching leg alignment side-to-side and keeping the pelvis level and neutral during unilateral work.", positions: [
      { label: "One Leg Bent", detail: "Ball of one foot on the footbar, aligned with the sit-bone (supporting leg). Other leg flexed in tabletop, ankle plantar flexed, toes gently pointed (gesture leg). Legs parallel." },
      { label: "Bicycle", detail: "Ball of one foot on the footbar, aligned with the sit-bone (supporting leg). Other leg extended over the footbar, ankle plantar flexed, toes gently pointed (gesture leg). Legs parallel. The gesture leg cycles through tabletop and full extension opposite the support leg's press." },
      { label: "Single Heel", detail: "Heel of one foot on the footbar, aligned with the sit-bone, ankle dorsiflexed (supporting leg). Other leg extended over the footbar, ankle dorsiflexed (gesture leg). Legs parallel." },
    ], modifications: ["Supporting ankle dorsiflexed (One Leg Bent).", "Laterally rotated supporting leg (One Leg Bent).", "Medially rotated supporting leg (One Leg Bent).", "Both ankles dorsiflexed (Bicycle).", "Flex the gesture leg (Single Heel).", "Laterally rotated supporting leg (Single Heel).", "Medially rotated supporting leg (Single Heel)."] , script: { lines: ["Let's move into Single Leg. Come to supine, one foot supporting on the bar, the other leg gesturing.", "Inhale to extend your supporting knee and press the carriage out; exhale to flex the supporting knee and hip, controlling the return. Notice the breath is reversed from Footwork — there's no second leg here to share the stabilizing work.", "We'll move through One Leg Bent, Bicycle, then Single Heel. Keep your pelvis level and square, and let your hip extensors and quadriceps on the supporting side do the pressing — don't let it rock or dip toward the working leg."] } },
    { name: "Hundred", level: "Essential", page: "34", springs: "2–3", startingPosition: "Supine, legs in tabletop or extended on the diagonal, straps in the hands.", pelvis: "Imprinted", spine: "Upper thoracic flexion", breathing: "Staccato breathing, 5 counts in / 5 counts out, to 100 pumps.", targetMuscles: "Transversus abdominis, rectus abdominis, obliques, hip flexors.", focus: "The Reformer version of the classic abdominal-endurance opener — resist the pull of the straps toward the pulleys.", modifications: ["Head on the carriage.", "Tabletop position.", "No straps.", "Feet on the footbar.", "Use a spacer.", "Flex & extend the legs, 5 counts each."] , script: { lines: ["Let's move into Hundred. Come to supine, legs in tabletop or extended on the diagonal, straps in your hands.", "Curl up into your abdominal flexion, then pump your arms in a staccato rhythm — five counts in, five counts out, up to a hundred.", "Lift just to your shoulder blades and keep your low back long — let your transversus abdominis and rectus abdominis hold the curl while your hip flexors keep your legs steady, resisting the pull of the straps rather than letting them yank your arms."] } },
    { name: "Bend & Stretch", level: "Essential", page: "36", springs: "2", startingPosition: "Supine, feet in straps, footbar #1, headrest as needed.", pelvis: "Neutral to start; imprint as the legs extend to the diagonal", spine: "Neutral", breathing: "Inhale to bend the knees toward the torso\nExhale to extend.", targetMuscles: "Hip flexors, quadriceps, deep abdominals stabilizing the pelvis against the moving legs.", focus: "An open-kinetic-chain footwork variant — the legs move independently of the carriage-pressing pattern, worked through three leg rotations.", positions: [
      { label: "Parallel", detail: "" },
      { label: "Laterally rotated", detail: "" },
      { label: "Medially rotated", detail: "" },
    ], modifications: ["Keep the ankles dorsiflexed throughout (Parallel, Laterally rotated)."] , script: { lines: ["Let's move into Bend and Stretch. Come to supine, feet in the straps.", "Inhale to bend your knees in toward your torso; exhale to extend your legs straight out. We'll work through parallel, turned out, and turned in.", "Keep your pelvis stable against the moving legs by engaging your deep abdominals, and feel your hip flexors and quadriceps driving the reach out — imprint only if you can't hold neutral."] } },
    { name: "Lift & Lower", level: "Essential", page: "38", springs: "2", startingPosition: "Supine, imprinted, feet in straps, footbar #1, legs straight and adducted, extended on the diagonal as low as imprint can be maintained.", pelvis: "Imprint to start; neutral as the legs hinge toward the torso", spine: "Neutral", breathing: "Inhale to hinge the legs up toward the ceiling (pelvis to neutral)\nExhale to lower the legs back to the diagonal (pelvis to imprint).", targetMuscles: "Hamstrings, gluteus maximus (hip extension control), deep abdominals.", focus: "Trains the transition between neutral and imprint under the load of the legs — a direct application of the Pelvic Placement principle.", positions: [
      { label: "Parallel", detail: "" },
      { label: "Laterally rotated", detail: "Heels together, toes apart." },
    ], cues: ["Hinge at the hips to float the legs toward the ceiling, imagining they're helium balloons drifting upward.", "Press the legs back down as if pressing through thick honey, imprinting the pelvis as you go.", "For laterally rotated: heels together, toes apart, reaching diagonally down like zipping up a tight pair of jeans from the heels to the navel."] , script: { lines: ["Let's move into Lift and Lower. Come to supine, imprinted, feet in the straps, legs extended on the diagonal.", "Inhale to hinge your legs up toward the ceiling as your pelvis moves to neutral; exhale to lower them back to the diagonal as your pelvis returns to imprint.", "Float the legs up like helium balloons, quadriceps engaged the whole time, then press them back down as if through thick honey, using your hamstrings and glutes to pull the legs down as you imprint — like zipping up a tight pair of jeans from your heels to your navel."] } },
    { name: "Adductor Stretch", level: "Essential", page: "40", springs: "2", startingPosition: "Supine, imprinted. Legs adducted and parallel, extended on a diagonal as low as imprint can be maintained. Feet in straps, ankles plantar flexed, toes gently pointed. Arms long by sides, palms down.", pelvis: "Imprint; moves toward neutral as the legs hinge in toward the torso", spine: "Neutral", breathing: "Inhale to hinge the legs toward the torso, not beyond a 90° angle at the hips, pelvis moving toward neutral as the carriage returns\nThen, carriage still: exhale to abduct (open) the legs\nInhale to adduct (close) them — repeat once more\nExhale to hinge the legs back away to the diagonal, imprinting the pelvis as low as it can be maintained.", targetMuscles: "Adductors (concentrically squeezing the legs closed, eccentrically controlling the open), hip extensors isometrically, transversus abdominis and deep pelvic floor stabilizing the lumbo-pelvic region.", focus: "A three-part sequence, not a side-to-side sweep — hinge the legs up to 90° at the hip, open and close them twice at the top, then hinge them back down; the pelvis only moves between imprint and neutral during the hinge, never during the open/close." , script: { lines: ["Let's move into Adductor Stretch. Come to supine, imprinted, feet in the straps, legs adducted and parallel, extended on the diagonal.", "Inhale to hinge your legs up toward your torso, no further than a 90-degree angle at the hips, letting your pelvis move toward neutral as the carriage returns. Then, keeping the carriage still, exhale to open your legs apart, inhale to squeeze them back together — twice.", "Exhale to hinge the legs back away to the diagonal, imprinting your pelvis again. Feel your adductors working to squeeze the legs closed and lengthening as they open — keep both legs moving evenly."] } },
    { name: "Short Spine Prep", level: "Essential", page: "41", springs: "2", startingPosition: "Supine, imprinted. Legs straight, adducted and laterally rotated, extended on a diagonal as low as imprint can be maintained. Feet in straps, ankles plantar flexed, toes gently pointed. Arms long by sides, palms down.", pelvis: "Imprint on the diagonal; moves toward neutral as the legs hinge in", spine: "Neutral throughout — no spinal articulation in the Prep", breathing: "Inhale to rotate the legs parallel, then hinge them toward the torso as far as the hamstrings allow, pelvis moving toward neutral\nExhale to deepen the hamstring stretch further, carriage still\nInhale to laterally rotate the legs again, flex the knees and dorsiflex the ankles, pulling the heels toward the sit-bones, carriage still\nExhale to press the feet into the straps and extend the legs, moving the carriage out, imprinting the pelvis to finish.", targetMuscles: "Transversus abdominis and deep pelvic floor, hip extensors and hamstrings eccentrically on the hinge, obliques stabilizing against rotation.", focus: "Prepares the hamstring-stretch hip-hinge and the knee-bend transition used in full Short Spine — but the spine never leaves the carriage here; the roll-up-overhead only appears in the full exercise.", modifications: ["Peroneal stretch — bring the soles of the feet together as the knees flex."] , script: { lines: ["Let's move into Short Spine Prep. Come to supine, imprinted, legs straight, adducted and laterally rotated, extended on the diagonal.", "Inhale to rotate your legs parallel and hinge them toward your torso as far as your hamstrings allow, letting your pelvis move toward neutral; exhale to deepen that stretch a little further.", "Inhale to turn your legs out again, bend your knees and flex your ankles, drawing your heels toward your sit-bones — the carriage stays still. Exhale to press your feet into the straps and extend your legs back out, imprinting your pelvis as you return.", "This is preparing your hip extensors and hamstrings for the full Short Spine — your spine stays on the carriage the whole time, only your legs and pelvis are moving."] } },
    { name: "Short Spine", level: "Essential", page: "42", springs: "2", startingPosition: "Same as Short Spine Prep — supine, imprinted, legs straight, adducted and laterally rotated, extended on a diagonal as low as imprint can be maintained, feet in straps, ankles plantar flexed.", pelvis: "Imprint to start; moves through neutral and full hip extension as the spine rolls up, back to imprint on the press out", spine: "Full sequential articulation — rolls off the carriage from tail to upper thoracic on the way up, and from upper thoracic back to tail on the way down", breathing: "Inhale to rotate the legs parallel and hinge toward the torso as far as the hamstrings allow, pelvis moving toward neutral\nExhale to sequentially roll the spine off the carriage from tail to upper thoracic, reaching the legs toward the ceiling as the carriage returns fully\nInhale to flex the knees and laterally rotate the legs just wider than shoulder-distance, pulling the heels toward the sit-bones, carriage still\nExhale to sequentially roll the spine back onto the carriage from upper thoracic, as far as possible without moving the carriage\nInhale to continue rolling the sacrum down, engaging the hamstrings to pull the heels toward the sit-bones, pelvis moving toward neutral\nExhale to press the feet into the straps and extend the legs, moving the carriage out, imprinting the pelvis to finish.", targetMuscles: "Transversus abdominis and deep pelvic floor; gluteus maximus and hamstrings eccentrically on the hinge, concentrically drawing the pelvis back over the femurs; rectus abdominis and obliques rolling the spine off the carriage, controlling it eccentrically on the way down; hip extensors, quadriceps and adductors on the press out; scapular stabilizers throughout.", focus: "A full spinal roll-up-and-over with a knee-bend at the top — sequence matters: hinge, roll up and overhead, bend the knees, roll back down, then press the legs out to finish.", modifications: ["Peroneal stretch (soles of the feet together)."] , script: { lines: ["Let's move into Short Spine. Come to supine, imprinted, same setup as the Prep — legs straight, turned out, extended on the diagonal, feet in the straps.", "Inhale to rotate your legs parallel and hinge toward your torso; exhale to roll your spine off the carriage, tail to upper thoracic, reaching your legs up and overhead as the carriage comes all the way in.", "Inhale to bend your knees and turn your legs out again, drawing your heels toward your sit-bones. Exhale to roll your spine back down onto the carriage from the top, as far as you can without the carriage moving.", "Inhale to finish rolling your sacrum down, using your hamstrings and glutes to draw your pelvis under you; exhale to press your feet into the straps, extend your legs, and imprint to finish."] } },
    { name: "Midback Series", level: "Essential", page: "44", springs: "1–2", startingPosition: "Supine, hands in straps, legs in tabletop.", pelvis: "Imprint", spine: "Neutral, elongated", breathing: "Inhale to prepare\nExhale to press the arms through each pattern.", targetMuscles: "Triceps, latissimus dorsi, pectorals, scapular stabilizers (varies by position).", focus: "Isolates several arm patterns against spring resistance while the legs hold a stable tabletop — an early scapular-stability test.", positions: [
      { label: "Triceps press", detail: "" },
      { label: "Straight down", detail: "" },
      { label: "45 degree", detail: "" },
      { label: "Sides", detail: "" },
      { label: "Circles", detail: "" },
    ], modifications: ["Palms facing hips (positions 1-2, 5).", "Palms facing up (positions 1-5).", "Palms facing down (positions 3-5)."] , script: { lines: ["Let's move into Midback Series. Come to supine, hands in the straps, legs in tabletop.", "Exhale to press your arms through each pattern — triceps press, straight down, on a diagonal, out to the sides, then circles.", "Keep your tabletop legs completely stable and your scapulae stabilized as your arms move against the springs — feel your triceps extending on the press, and your latissimus dorsi and pectorals taking over as the arm angle changes through each position."] } },
    { name: "Back Rowing Preps", level: "Essential", page: "49", springs: "1–2", startingPosition: "Seated facing the back of the Reformer, straps in the hands, legs crossed or between the shoulder rests.", pelvis: "Neutral to posterior tilt during the roll-down positions", spine: "Neutral to flexion during roll-down positions", breathing: "Inhale to prepare/reach\nExhale to row/pull.", targetMuscles: "Rhomboids, mid trapezius, posterior deltoid, biceps/triceps depending on position.", focus: "Builds the whole back-rowing vocabulary used constantly through the rest of the Reformer repertoire.", positions: [
      { label: "Plow", detail: "" },
      { label: "Open Elbow", detail: "" },
      { label: "Airplane", detail: "" },
      { label: "Biceps Curl", detail: "" },
      { label: "Triceps", detail: "" },
      { label: "Roll Down", detail: "" },
      { label: "Roll Down Biceps", detail: "" },
      { label: "Roll Down Obliques", detail: "" },
    ], modifications: ["Palms facing forward (1, 3).", "Palms facing hips (1).", "Palms facing down (3, 4, 5, 7).", "Palms facing in (4).", "Supination/pronation of the forearms (4, 7).", "Palms facing up (5).", "Alternative sitting (1-8) on a cushion, platform extender, or box."] , script: { lines: ["Let's move into Back Rowing Preps. Come to seated, facing the back of the Reformer, straps in your hands.", "Inhale to prepare and reach; exhale to row or pull. We'll build through the whole rowing vocabulary — plow, open elbow, airplane, biceps curl, triceps, then three roll-down variations.", "Open your chest as your elbows draw back, feeling your rhomboids and mid-trapezius squeezing your shoulder blades together and your posterior deltoids driving the pull — keep your ribs stacked over your pelvis rather than arching to compensate."] } },
    { name: "Side Arm Preps Sitting", level: "Essential", page: "58", springs: "0.25–1", startingPosition: "Seated sideways, legs crossed or dangling.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Inhale to prepare/open\nExhale to close/pull.", targetMuscles: "Latissimus dorsi, pectoralis major (adduction), deltoids (abduction), rotator cuff (internal/external rotation).", focus: "Isolates shoulder rotation and horizontal ab/adduction while the torso resists being pulled off balance by the spring.", positions: [
      { label: "Internal Rotation", detail: "" },
      { label: "External Rotation", detail: "" },
      { label: "Adduction", detail: "Pull the arm across the front of the body toward the opposite hip, like drawing a line across your body — feel latissimus dorsi working; don't let the spring rotate the torso toward the pulley." },
      { label: "Abduction", detail: "Push the arm across the front of the body, elbow reaching out to the side like a hinged door opening — keep the wrist long and neutral, don't let the shoulder hike toward the ear." },
    ], modifications: ["Palms facing up (1-4).", "Palms facing down (1-4).", "Alternative sitting (1-4) on a cushion, platform extender, or box."] , script: { lines: ["Let's move into Side Arm Preps Sitting. Come to seated sideways, legs crossed or dangling.", "Inhale to prepare and open; exhale to close or pull. We'll move through internal rotation, external rotation, adduction, and abduction.", "Keep your torso tall and still — don't let the spring pull you off balance toward the pulley. Feel your rotator cuff driving the two rotations, and your latissimus dorsi and deltoids taking over for adduction and abduction."] } },
    { name: "Side Twist Sitting", level: "Essential", page: "62", springs: "0.5–1", startingPosition: "Seated sideways with a strap or Fitness Circle® held in front of the xiphoid process.", pelvis: "Neutral", spine: "Rotation with axial elongation", breathing: "Inhale to lengthen\nExhale to rotate.", targetMuscles: "Obliques, deep spinal rotators.", focus: "Pure seated rotation against light spring resistance.", modifications: ["Alternative sitting on a cushion, platform extender, or box.", "Hands further away for a bigger circle."] , script: { lines: ["Let's move into Side Twist Sitting. Come to seated sideways, holding a strap or Fitness Circle in front of your sternum.", "Inhale to lengthen tall; exhale to rotate your torso away from the pulley.", "Keep the rotation pure — no leaning or shifting your pelvis, just your obliques and deep spinal rotators turning your torso."] } },
    { name: "Front Rowing Preps", level: "Essential", page: "64", springs: "1–2", startingPosition: "Seated facing the front of the Reformer, legs crossed.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Inhale to prepare\nExhale to row/press.", targetMuscles: "Deltoids, pectorals, biceps (Offering position), scapular stabilizers.", focus: "Front-facing rowing vocabulary — mirrors Back Rowing Preps but works the anterior chain.", positions: [
      { label: "Straight Forward", detail: "" },
      { label: "2nd Position", detail: "" },
      { label: "Offering", detail: "" },
    ], modifications: ["Palms face in / face back (position 1).", "Palms face up / face down (position 2).", "Pronation/supination of the forearms (position 3).", "Omit opening the arms to the side (position 3).", "Alternative sitting on a cushion, platform extender, or box."] , script: { lines: ["Let's move into Front Rowing Preps. Come to seated facing the front of the Reformer, legs crossed.", "Inhale to prepare; exhale to row or press. We'll move through straight forward, second position, then Offering.", "Sit tall through your whole spine before each press, and keep your shoulder blades drawing down as your deltoids and pectorals drive the press forward."] } },
    { name: "Stomach Massage", level: "Essential", page: "68–70", springs: "2–3", startingPosition: "Seated on the carriage, balls of the feet on the footbar — exact seat position and hand placement vary by position below.", pelvis: "Posterior tilt (Prep, Round Back) or neutral (Straight Back)", spine: "Flexion (Prep, Round Back) or axial elongation (Straight Back)", breathing: "Prep: exhale to engage the abdominals and press the carriage out a few inches staying back of the sit-bones\nInhale to maintain the flexion and control the return\nRound Back/Straight Back: one continuous inhale through the press-out, heel lower and heel lift\nThen exhale to flex the knees and return the carriage — see positions below.", targetMuscles: "Transversus abdominis and deep pelvic floor; rectus abdominis and obliques (Prep); hip extensors, quadriceps and adductors concentrically pressing out, eccentrically on the return; gastrocnemius and soleus at the heels; psoas maintaining the seated position (Round Back/Straight Back).", focus: "The foundational seated leg-press pattern, built up from a simple prep into two full spinal positions.", positions: [
      { label: "Prep", detail: "Seated on the gripper mat in the center of the carriage, weight back of the sit-bones, spine flexed in a C-curve, shoulders over hips, knees flexed, balls of feet on the footbar just wider than shoulder-distance, hands between the feet holding the center of the bar. Begin by breathing without moving the carriage, feeling the abdominals flatten and the lumbar spine lengthen; then exhale to press the carriage out a few inches, inhale to control the return." },
      { label: "Round Back", detail: "Seated back of the sit-bones in a C-curve, legs laterally rotated, heels together toes apart, balls of feet on the bar, arms rounded under the thighs or fingertips lightly touching the sides of the carriage. One continuous inhale: extend the knees to press the carriage out lifting the heels, then lower and lift the heels once more before the carriage returns; exhale to flex the knees and return the carriage, staying back of the sit-bones." },
      { label: "Straight Back", detail: "Same seated leg-press pattern, hands on top of or beside the shoulder rests, spine held in a tall neutral line instead of a C-curve. Same one continuous inhale through the press-out and heel lower/lift, exhale to flex the knees and return." },
    ], modifications: ["Omit the lower-and-lift of the heels (Round Back/Straight Back)."] , script: { lines: ["Let's move into Stomach Massage. Come to seated on the gripper mat, weight just behind your sit-bones, balls of your feet on the bar.", "In the Prep, exhale to press the carriage out a few inches and inhale to control it back in, feeling your abdominals flatten and your lumbar spine lengthen. In Round Back, turn your legs out, heels together, and take one long inhale through pressing out, lowering your heels, then lifting them, before exhaling to flex your knees and return. Straight Back repeats that same breath with your spine held tall instead of curved.", "Initiate every press with your deep abdominals and hip extensors, not just your knees extending, and keep your weight back of your sit-bones throughout — feel a widening across your lower back, not a stretch in your hamstrings."] } },
    { name: "Arms Pulling Straps — Long Box", level: "Essential", page: "72", springs: "0.5–1", startingPosition: "Prone on the long box, upper body flexed with the head relaxed off the end of the box, legs straight and adducted, hands in the ropes.", pelvis: "Neutral", spine: "Flexion–extension (Plow, Airplane), elongation (Triceps)", breathing: "Plow/Airplane — four breaths: inhale to slide the scapulae down and begin pulling the arms back, moving the carriage out and lengthening the spine to neutral\nExhale to continue pulling the arms back to hip level and extend the upper spine\nInhale to reach the arms toward the floor (or out to the sides) and begin returning the carriage, lengthening the spine back to neutral\nExhale to reach the arms forward and fully return the carriage.\n5 reps.\nTriceps — exhale to extend the elbows and move the carriage out\nInhale to flex the elbows and return\n5 reps (10 for Advanced prep).", targetMuscles: "Rhomboids, mid trapezius, posterior deltoid, triceps, erector spinae.", focus: "Prone rowing that builds thoracic extension strength alongside the pull.", positions: [
      { label: "Plow", detail: "" },
      { label: "Airplane", detail: "" },
      { label: "Triceps", detail: "" },
    ], modifications: ["Plow, Airplane: omit the arm-pulling, practice spinal extension/flexion only."] , script: { lines: ["Let's move into Arms Pulling Straps on the Long Box. Come to prone, upper body flexed over the end of the box, hands in the ropes.", "Inhale to slide your shoulder blades down and begin pulling your arms back, lengthening your spine to neutral; exhale to continue pulling through Plow or Airplane, then reach forward to return. For Triceps, exhale to extend your elbows, inhale to bend and return.", "Build the pull from your upper back extending — rhomboids, mid-trapezius and posterior deltoids driving the row, triceps finishing the press in Triceps — not by yanking with your arms."] } },
    { name: "Round Back — Short Box", level: "Essential", page: "76", springs: "2", startingPosition: "Seated upright on the short box, pelvis and spine neutral. Legs adducted, feet hooked under the footstrap. Hands clasped together, one wrist held in the other, in front of the lower abdomen. Scapulae stabilized.", pelvis: "Neutral to start; rolls into posterior tilt as the lumbar spine flexes back", spine: "Neutral to start, flexing into a C-curve as the torso rolls back, then folding forward over the legs before resequencing to neutral", breathing: "Exhale to roll the pelvis away from the front of the femurs and flex the lumbar spine into a C-curve, only as far as the abdominals stay flat\nInhale to maintain that flexion and lift the arms overhead, scapulae stabilized\nExhale to lower the arms and use the abdominals to fold the torso forward over the legs, weight coming onto the top of the sit-bones\nInhale to sequentially lengthen the spine from tail to head, returning to the seated neutral start.", targetMuscles: "Transversus abdominis and deep pelvic floor; rectus abdominis and obliques concentrically creating and isometrically holding the flexion; gluteus maximus and hamstrings drawing the back of the pelvis toward the back of the femurs; scapular stabilizers as the arms lift and lower.", focus: "A four-part sequence, not a simple roll-back-and-up — roll into the C-curve, lift the arms overhead, fold forward over the legs, then resequence back to sitting tall; the arms lift and lower, they don't circle.", script: { lines: ["Let's move into Round Back on the Short Box. Come to seated upright, legs together, feet hooked under the strap, hands clasped together at your lower abdomen.", "Exhale to roll your pelvis away from your femurs, flexing into a C-curve only as far as your abdominals stay flat and connected. Inhale to hold that flexion and lift your arms overhead, scapulae stabilized.", "Exhale to lower your arms and use your abdominals to fold your torso forward over your legs; inhale to sequentially lengthen your spine from tail to head, stacking back up to seated.", "Let your rectus abdominis and obliques initiate and hold the curve, and your glutes and hamstrings draw your pelvis under you — the arms lift and lower, they don't circle out to the sides."] } },
    { name: "Straight Back — Short Box", level: "Essential", page: "77", springs: "2", startingPosition: "Seated upright on the short box, pelvis and spine neutral. Legs adducted, feet hooked under the footstrap. Arms straight, shoulder-distance apart, holding a pole overhead the whole time. Scapulae stabilized.", pelvis: "Neutral", spine: "Neutral elongated — stays rigid throughout; the pole overhead never moves relative to the torso", breathing: "Inhale to stay/hold the starting position\nExhale to hinge the pelvis away from the front of the femurs, maintaining a neutral spine, hinging as far as possible without changing the spine\nInhale to maintain that hinged position\nExhale to return to the vertical seated position, weight directly on the sit-bones.", targetMuscles: "Transversus abdominis and deep pelvic floor; erector spinae, rectus abdominis and obliques isometrically preventing extension of the spine; scapular stabilizers holding the arms overhead.", focus: "A pure hip-hinge — the pole stays fixed overhead the whole exercise, it is never pressed or lowered; movement happens only at the hip joint while the spine stays rigid like a plank.", modifications: ["Imprint slightly if a neutral spine can't be stabilized during the hinge back, returning to neutral as the torso returns to vertical."], script: { lines: ["Let's move into Straight Back on the Short Box. Come to seated, legs together, feet under the strap, holding a pole overhead — it stays there the whole exercise.", "Exhale to hinge your pelvis away from your femurs, keeping your spine completely neutral and rigid; inhale to hold that hinged position.", "Exhale to return to vertical, weight landing directly on your sit-bones.", "Imagine your spine as a solid rod from tailbone to crown — your abdominals and erector spinae hold it still while the movement happens only at your hips, like a door hinge."] } },
    { name: "Twist — Short Box", level: "Essential", page: "79", springs: "2", startingPosition: "Seated upright on the short box, pelvis and spine neutral. Legs adducted, feet hooked under the footstrap (may also be done with legs adducted, knees flexed and feet on the carriage). Arms straight, reaching out to the sides, palms down.", pelvis: "Neutral — stays still throughout to isolate the rotation", spine: "Rotation with axial elongation — torso stays vertical the whole time, there is no hip-hinge here", breathing: "Exhale for three counts, rotating the spine — rotate maximally on the first count, then lengthen and increase the rotation with the next two\nInhale to lengthen and return to center\nComplete 5 repetitions on each side, alternating.", targetMuscles: "External oblique on the rotating side and internal oblique on the opposite side concentrically to rotate the spine, eccentrically on the return; erector spinae and obliques maintaining the vertical torso; scapular stabilizers.", focus: "Pure spinal rotation, like Spine Twist on the Mat — the torso stays upright and the pelvis stays still the whole time; there is no hinging back as in Straight Back or Tree.", modifications: ["Reverse breath — inhale to rotate, exhale to return, once scapular stabilization is secure.", "Flex the back elbow to increase rotation and emphasize mid/low trapezius.", "Hold a Fitness Circle® against the ribcage for scapular stabilization and to isolate the rotation."] , script: { lines: ["Let's move into Twist on the Short Box. Come to seated, legs together, feet under the strap, arms out to the sides.", "Exhale for three counts, rotating your spine away from center — rotate as far as you can on the first count, then use the next two counts to lengthen and rotate a little further. Inhale to lengthen and return to center.", "Keep your pelvis completely still and your torso upright the whole time — this is pure rotation, no hinging back, initiated from your obliques low in your spine and spiraling up."] } },
    { name: "Tree — Short Box", level: "Essential", page: "80", springs: "2", startingPosition: "Seated upright on the short box, pelvis square to front, sitting as tall and neutral as possible without gripping the hip flexors. One foot hooked under the footstrap. Other leg flexed, inside hand under the knee, outside hand reaching the ankle.", pelvis: "Square and neutral throughout the knee extensions; rolls into flexion only on the final repetition's roll-down", spine: "Neutral, elongated through the knee extensions; sequentially flexes and re-extends on the roll-down/up", breathing: "Exhale to keep the pelvis square and extend the gesture knee, lengthening the hamstrings while staying as upright as possible\nInhale to flex the knee back to start — complete 3 repetitions\nOn the last repetition, inhale to keep the leg straight and place the other hand on the ankle\nExhale to initiate by rolling the ASIS away from the femurs, flexing the lumbar spine and rolling the sacrum onto the box as the hands walk down the back of the leg\nInhale to stay, breathing into the sides of the ribcage\nExhale to initiate with the abdominals to return to sitting, walking the hands back up the leg to the ankle\nRepeat 3 times on each side.", targetMuscles: "Quadriceps of the gesture leg concentrically extending the knee as the hamstrings lengthen; rectus abdominis and obliques concentrically creating the roll-down flexion; hip flexors of the supporting leg eccentrically controlling the roll down; obliques and multifidus preventing rotation.", focus: "Stays seated on the box throughout — there is no standing balance in this exercise. Extend and flex the gesture knee three times first, then on the last rep add the seated roll-down and roll-up, walking the hands along the leg.", modifications: ["Omit the roll back — repeat only the knee extension.", "Flex the top knee throughout."] , script: { lines: ["Let's move into Tree on the Short Box. Come to seated, one foot under the strap, the other leg flexed with your inside hand under the knee and outside hand at the ankle.", "Exhale to extend that knee, lengthening your hamstrings while staying as tall as possible; inhale to flex it back in. Repeat this three times.", "On the last repetition, walk your hands down the back of your leg as you exhale to roll your pelvis and lumbar spine down onto the box; inhale to stay there, breathing into your ribcage.", "Exhale to use your abdominals to roll back up to seated, walking your hands back up to your ankle — you stay seated on the box the whole time, there's no standing balance in this one."] } },
    { name: "Elephant", level: "Essential", page: "82", springs: "1–2", startingPosition: "Standing, hands on the footbar, heels against the shoulder rests, pelvis over the feet, ankles dorsiflexed.", pelvis: "Posterior tilt (Round Back) or Neutral (Straight Back)", spine: "Flexion (Round Back) or neutral, elongated (Straight Back)", breathing: "Inhale to press the carriage out\nExhale to draw it in.", targetMuscles: "Hamstrings, deep abdominals, calves, glutes (Straight Back).", focus: "A standing hip-hinge/carriage press performed in two spinal positions.", positions: [
      { label: "Round Back", detail: "Flexed spine — stretches the hamstrings while holding a C-curve." },
      { label: "Straight Back", detail: "Neutral, elongated spine — the same pattern with a harder hamstring/core combination." },
    ], modifications: ["Move the feet forward.", "High half-toe."] , script: { lines: ["Let's move into Elephant. Come to standing, hands on the footbar, heels against the shoulder rests, hips hinged over your feet.", "Exhale to draw the carriage in; inhale to let it glide back out. We'll do this in Round Back, then Straight Back.", "Hinge from your hips, not by rounding your low back — feel your hamstrings lengthening and your glutes and deep abdominals controlling the hinge as the carriage moves out."] } },
    { name: "Mermaid", level: "Essential", page: "84", springs: "1", startingPosition: "Seated upright facing square to one side, pelvis and spine as neutral as possible, knees flexed, one leg internally rotated with the lower leg against the shoulder rests, other leg externally rotated with the foot against the opposite knee. Pelvis square and as level as possible. Heel of one hand on the footbar, other hand on the shoulder rest. Scapulae stabilized.", pelvis: "Neutral", spine: "Lateral flexion toward the footbar and toward the shoulder rests, alternating sides", breathing: "Inhale to keep the scapula stable and reach the shoulder-rest-side arm from the shoulder rest overhead\nExhale to laterally flex the spine toward the footbar, simultaneously pressing the carriage out by abducting the arm on the footbar — the overhead arm stays reaching up\nInhale to adduct the arm on the footbar to return the carriage as the spine returns to vertical, overhead arm still reaching up\nExhale to lower the overhead arm back to the shoulder rest\nInhale to reach that same arm (now off the footbar) overhead\nExhale to laterally flex the spine toward the shoulder rests\nInhale to return the spine to vertical, arm still overhead\nExhale to return the arm to the footbar\nComplete the entire sequence 3–5 times on each side.", targetMuscles: "Obliques (lateral flexion), latissimus dorsi and deltoids of the footbar arm pressing the carriage out, scapular stabilizers of the overhead reaching arm.", focus: "The footbar arm is what presses the carriage out — one arm drives the press while flexing toward the footbar, then the pattern reverses so the other arm takes over the press while flexing toward the shoulder rests, all before switching sides.", modifications: ["Alternative sitting on a cushion, platform extender, or box, or dangling the legs.", "Knees together."] , script: { lines: ["Let's move into Mermaid. Come to seated square to one side, heel of one hand on the footbar, other hand on the shoulder rest.", "Inhale to reach your shoulder-rest arm overhead; exhale to laterally flex toward the footbar while pressing the carriage out with your footbar arm — your overhead arm stays lifted. Inhale to return the carriage and your spine to vertical.", "Exhale to lower the overhead arm, then inhale to reach that same arm up instead; exhale to flex toward the shoulder rests, inhale to return to vertical, exhale to lower back to the footbar.", "It's your footbar-side latissimus dorsi and deltoid pressing the carriage, while your obliques do the lateral flexion — the overhead arm is just reaching, it isn't doing the work."] } },
    { name: "Leg Circles", level: "Essential", page: "86", springs: "2", startingPosition: "Supine, imprinted. Legs straight, adducted and parallel, extended on a diagonal as low as imprint can be maintained. Feet in straps, ankles plantar flexed, toes gently pointed. Arms long by sides, palms down.", pelvis: "Imprint; moves toward neutral as the legs hinge in before each circle", spine: "Neutral", breathing: "Inhale to hinge the legs toward the torso as far as the hamstrings allow, pelvis moving toward neutral\nExhale to abduct the legs, circling them as they press away from the torso to move the carriage out, adducting the legs together again at the bottom of the circle, imprinting the pelvis\nReverse: inhale to abduct the legs as they circle out and hinge toward the torso, adducting at the top of the circle\nExhale to press the adducted legs away from the torso, imprinting the pelvis\nComplete 10 repetitions in each direction.", targetMuscles: "Hip flexors and extensors driving the hinge, adductors/abductors circling the legs, deep pelvic stabilizers keeping the pelvis still.", focus: "Every circle starts with a hip-hinge, not a sweep from the diagonal — the legs hinge up toward the torso first, then open, circle, and press away to close the shape.", positions: [
      { label: "Parallel", detail: "" },
      { label: "Laterally rotated", detail: "" },
      { label: "Medially rotated", detail: "" },
    ], modifications: ["Small quick circles, maintaining imprint throughout (Parallel, Laterally rotated)."] , script: { lines: ["Let's move into Leg Circles. Come to supine, imprinted, feet in the straps, legs extended on the diagonal.", "Inhale to hinge your legs up toward your torso, hamstrings lengthening, pelvis moving toward neutral. Exhale to open your legs and circle them out and around, pressing them away to move the carriage out, closing the legs together at the bottom and imprinting your pelvis.", "Reverse the circle for the next set: inhale to open the legs as they circle out and hinge back toward your torso; exhale to press the closed legs away. Keep your pelvis completely still — if it rocks, make the circle smaller."] } },
    { name: "Knee Stretches", level: "Essential", page: "89–91", springs: "2", startingPosition: "Kneeling on the carriage, hands on the footbar — exact foot placement varies by position below.", pelvis: "Neutral (Prep), posterior tilt (Round Back), or neutral (Straight Back)", spine: "Articulated flexion (Prep, Round Back) or neutral, elongated (Straight Back)", breathing: "Prep: the carriage does not move at all — inhale to maintain a neutral spine\nExhale to sequentially articulate the spine into flexion from tail to head\nInhale to hold that flexion breathing into the ribcage\nExhale to sequentially articulate back to neutral from tail to head\nRound Back/Straight Back: inhale to extend the hips and knees, pressing the carriage out\nExhale to flex them, returning it — see positions below.", targetMuscles: "Rectus abdominis and obliques flexing the spine (Prep); hip extensors, quadriceps and adductors pressing the carriage out, hip flexors returning it (Round Back/Straight Back); scapular stabilizers throughout.", focus: "The Prep never moves the carriage — it's pure spinal articulation, like a kneeling Cat Stretch. Only Round Back and Straight Back press the carriage in and out.", positions: [
      { label: "Prep", detail: "Kneeling with feet against the shoulder rests, hands on the footbar, pelvis and spine neutral, sitting back toward the heels. Carriage stays completely still: exhale to sequentially flex the spine from tail to head, inhale to hold and breathe into the ribcage, exhale to sequentially return to neutral from tail to head." },
      { label: "Round Back", detail: "Kneeling, feet against the shoulder rests, spine flexed, back of the pelvis drawn toward the back of the femurs; inhale to extend the hips and knees pressing the carriage out as far as possible without changing the pelvis or spine, exhale to flex the hips and knees to return it. Core control under a moving base." },
      { label: "Straight Back", detail: "Kneeling, feet against the shoulder rests, spine as neutral and elongated as possible; same breath as Round Back — inhale to press the carriage out, exhale to return — a harder isometric core demand since the spine can't flex to help." },
    ], modifications: ["Reverse sequencing (Prep) — initiate the articulation from head to tail instead.", "Standing variant: one foot on the floor, other knee flexed on the carriage (Round Back/Straight Back)."] , script: { lines: ["Let's move into Knee Stretches. Come to kneeling on the carriage, hands on the footbar.", "In the Prep, the carriage doesn't move at all — exhale to curl your spine into flexion from tail to head, inhale to hold and breathe into your ribcage, exhale to sequentially return to neutral.", "In Round Back and Straight Back, inhale to extend your hips and knees, pressing the carriage out as far as you can without changing your pelvis or spine; exhale to flex and return it. Keep a long line from your knees to the crown of your head — don't let your low back round to compensate."] } },
    { name: "Running", level: "Essential", page: "92", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral. Balls of feet on the footbar, ankles plantar flexed. Legs parallel and adducted. Arms long by sides, palms down.", pelvis: "Neutral — stays still, only the legs move", spine: "Neutral", breathing: "Inhale to maintain heels lifted and extend the knees to press the carriage out\nThen, alternating: exhale to keep one knee extended and lower that heel under the footbar (dorsiflex) while flexing the opposite knee (maintaining its plantar flexion) — the carriage returns slightly\nInhale to lift that heel (plantar flex) and extend the opposite knee, returning both legs straight — the carriage moves out slightly\nRepeat, lowering the other heel, alternating for 20–60 repetitions\nExhale to finish, keeping the heels lifted and flexing the knees to return the carriage.", targetMuscles: "Gastrocnemius and soleus concentrically as the heels lift, eccentrically as they lower; obliques preventing spinal extension and rotation; vastus medialis and lateralis tracking the patella evenly.", focus: "Press the carriage all the way out first, then alternate dropping one heel at a time under the bar while the other stays lifted — the pelvis doesn't move, only the legs and ankles.", script: { lines: ["Let's move into Running. Come to supine, balls of your feet on the bar, legs parallel and adducted.", "Inhale to keep your heels lifted and extend your knees, pressing the carriage all the way out.", "Then alternate: exhale to lower one heel under the bar as the other knee bends, inhale to lift that heel and straighten both legs again. Keep switching, light and quick, and keep your calves and pelvis doing the work — not a bounce in your low back."] } },
    { name: "Hip Lift", level: "Essential", page: "95", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral. Heels on the footbar, ankles dorsiflexed. Legs parallel and abducted, hip-distance apart. Arms long by sides, palms down.", pelvis: "Neutral; lifts just off the carriage into a shallow, constant-height hover for the whole set", spine: "Neutral", breathing: "Inhale to stay\nExhale to stabilize the pelvis and spine in neutral and lift the pelvis just off the carriage, hovering\nInhale to stay\nThen, holding that same hover height: exhale to extend the knees and press the carriage out, making one line from shoulders to heels\nInhale to flex the knees and return the carriage — repeat 10 times without the pelvis ever rising higher\nExhale to lower the pelvis back down to the carriage to finish.", targetMuscles: "Rectus abdominis, obliques and erector spinae stabilizing the torso; hamstrings holding the pelvis at a constant height; hip extensors and quadriceps concentrically pressing the carriage out, eccentrically on the return.", focus: "The pelvis lifts only to a shallow hover once, then stays at that exact height for all 10 presses — this is not a full bridge like Hip Rolls; if the hips keep rising with each rep, the height isn't being held.", script: { lines: ["Let's move into Hip Lift. Come to supine, heels on the footbar, ankles flexed, legs parallel, hip-distance apart.", "Exhale to lift your pelvis just into a shallow hover off the carriage — this height stays constant for the whole set.", "From that hover, exhale to extend your knees and press the carriage out into one long line from shoulders to heels; inhale to flex your knees and return. Repeat ten times, using your hamstrings to keep your hips from climbing any higher, then exhale to lower back down."] } },
    { name: "Hip Rolls", level: "Essential", page: "96", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral. Heels on footbar, ankles dorsiflexed. Legs parallel and abducted, hip-distance apart. Arms long by sides, palms down.", pelvis: "Neutral to full hip extension at the top of the bridge, back to neutral", spine: "Full sequential articulation off and onto the carriage", breathing: "Exhale to sequentially articulate the spine off the carriage, tail to upper thoracic, without moving the carriage, until the hips are as extended as possible and the spine is neutral\nInhale to stay, reaching the knees over the footbar\nExhale to extend the knees to press the carriage out, lowering the pelvis to make one line from shoulders to heels\nInhale to flex the knees to return the carriage, lifting the pelvis to extend the hips as much as possible, keeping the weight on the upper thoracic\nExhale to sequentially articulate the spine back onto the carriage, upper thoracic to tail, without moving the carriage, returning to neutral.", targetMuscles: "Rectus abdominis and obliques concentrically flexing the spine off the carriage; gluteus maximus and hamstrings concentrically on the roll up, eccentrically on the roll down; quadriceps concentrically extending the knees to press out; hamstrings concentrically flexing the knees to pull the carriage in.", focus: "Two halves, not one — first a full bridge roll-up with the carriage still, then a repeated press-out/press-in phase where the pelvis rises and falls between a shoulder-to-heel line and a full hip extension, before rolling the spine back down.", modifications: ["Prep — omit the knee extension, like the Mat Hip Rolls warm-up."] , script: { lines: ["Let's move into Hip Rolls. Come to supine, heels on the footbar, ankles flexed.", "Exhale to peel your spine up off the still carriage, tail to upper thoracic, until your hips are fully extended; inhale to reach your knees out over the bar.", "Exhale to extend your knees, pressing the carriage out into one line from shoulders to heels; inhale to flex your knees, returning the carriage while lifting your pelvis into even more hip extension, weight staying on your upper back.", "Exhale to sequentially roll your spine back down onto the carriage, upper thoracic to tail. Your glutes and hamstrings power the lift, your quadriceps the press — this is Shoulder Bridge with an added press-out phase, not just a roll up and down."] } },
    { name: "Single Thigh Stretch", level: "Essential", page: "98", springs: "2", startingPosition: "Lunge position, one knee flexed with the foot against the shoulder rest, the other foot's ball on the footbar in line with the sit bones.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Inhale to lengthen\nExhale to press.", targetMuscles: "Hip flexors (stretch on the back leg), quadriceps, glutes (front leg).", focus: "A standing lunge/stretch pattern that also challenges balance on the moving carriage.", modifications: ["Reach one arm overhead.", "Standing thigh stretch variant off the Reformer."] , script: { lines: ["Let's move into Single Thigh Stretch. Come to a lunge, one knee bent with your foot against the shoulder rest, the other foot's ball on the footbar.", "Inhale to lengthen; exhale to press the carriage out.", "Keep your torso tall and stacked — feel the stretch through the hip flexor of your back leg as your front leg's quadriceps and glutes press the carriage out."] } },
    { name: "Side Splits", level: "Essential", page: "100", springs: "0.5–2", startingPosition: "Standing on the Reformer, facing to the side. One foot on the wooden standing platform, one foot on the edge of the carriage (hip-distance apart if using a platform extender). Spine and pelvis neutral, legs straight and parallel. Arms straight, reaching out to the sides, palms down or forward.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Abduction position: exhale to press the legs evenly away from the midline, opening and moving the carriage out\nInhale to draw the legs evenly toward the midline, returning it\nAdduction position: the breath reverses — inhale to control the carriage as the legs open evenly away from the midline\nExhale to draw the legs evenly toward the midline, returning it\nComplete 8–10 repetitions on each side.", targetMuscles: "Abduction: hip abductors concentrically pressing the carriage out, eccentrically on the return. Adduction: hip adductors eccentrically controlling the carriage out, concentrically drawing it back. Obliques and erector spinae stabilize the torso in both.", focus: "A standing balance and leg-strength finisher, testing control on an unstable, moving carriage — note the breath reverses between the two positions, since each targets the opposite muscle group.", positions: [
      { label: "Abduction", detail: "Heavier springs suit this direction — legs start adducted together, then press open." },
      { label: "Adduction", detail: "Lighter springs suit this direction — legs start open wide, then draw together." },
    ], modifications: ["Legs laterally rotated.", "Hands on the hips."] , script: { lines: ["Let's move into Side Splits. Come to standing, one foot on the platform, one foot on the carriage, arms out to the sides.", "In the Abduction direction, exhale to press your legs open evenly away from the midline; inhale to draw them back together. In Adduction, it reverses — inhale as your legs open, exhale as your hip adductors draw them back to center.", "Reach both legs away from each other evenly, and keep your pelvis level — don't let one hip hike."] } },
  ],
  intermediate: [
    { name: "Footwork (Intermediate)", level: "Intermediate", page: "22–27", springs: "3–4", startingPosition: "Supine, pelvis and spine neutral, footbar position #1, headrest adjusted for the individual.\nArms long by the sides of the body, palms down.\nSame five foot positions as the Essential version, worked through in sequence.", pelvis: "Neutral", spine: "Neutral", breathing: "Manual header: \"Same as Essential except Breathing.\" Reversed from Essential — inhale to press the carriage out (inhale expands the ribs and challenges abdominal stability)\nExhale to return.", targetMuscles: "Transversus abdominis, deep pelvic floor, obliques and multifidus (anti-extension/anti-rotation), hip extensors, quadriceps and adductors, vasti (patellar tracking) — same target muscles as the Essential version.", focus: "Re-lists the Essential five-position Footwork series for Intermediate level with the breath pattern reversed.\nManual note: once the reversed breath is secure, progress with \"1 speed + 2 springs\" (i.e. increase tempo and/or spring load) for Footwork and Second Position together.", positions: [
      { label: "Toes apart, heels together", detail: "" },
      { label: "Wrap toes on bar", detail: "" },
      { label: "Heels on bar", detail: "" },
      { label: "High half-toe", detail: "" },
      { label: "Lower & lift", detail: "" },
    ] , script: { lines: ["Let's move into Footwork. Same five foot positions as before, but now reverse your breath — inhale as you press the carriage out, exhale as you return.", "This challenges your abdominal stability on the harder part of the breath — keep your ribs and pelvis just as connected.", "Once this reversed breath feels secure, we can add speed or spring load."] } },
    { name: "Second Position (Intermediate)", level: "Intermediate", page: "28–29", springs: "3–4", startingPosition: "Supine, pelvis and spine neutral, footbar position #1, headrest adjusted for the individual.\nSame three leg rotations as the Essential version.", pelvis: "Neutral", spine: "Neutral", breathing: "Manual header: \"Same as Essential — Except Breathing.\" Reversed from Essential — inhale to press the carriage out\nExhale to return.", targetMuscles: "Adductors/abductors depending on rotation, quadriceps, glutes — same target muscles as the Essential version.", focus: "Re-lists the Essential three-rotation Second Position series for Intermediate level with the breath pattern reversed.", positions: [
      { label: "Parallel", detail: "" },
      { label: "Laterally rotated", detail: "" },
      { label: "Medially rotated", detail: "" },
    ] , script: { lines: ["Let's move into Second Position, same three rotations as before, with the breath reversed — inhale to press out, exhale to return.", "Keep your knees tracking over your feet through each rotation, just like before.", "Notice how the reversed breath changes where the real challenge sits — usually right as the carriage is fully extended, working your adductors, abductors, quadriceps and glutes depending on the rotation."] } },
    { name: "Single Leg (Intermediate)", level: "Intermediate", page: "30–34", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral, footbar position #1, headrest adjusted for the individual.\nBall of one foot on the footbar aligned with the sit-bone (supporting leg)\nOther leg gestures per position below.", pelvis: "Neutral", spine: "Neutral", breathing: "Manual header: \"same as Essential, Except?\" — reversed from Essential — inhale to press the carriage out\nExhale to return\nAdds a fourth position, Developé, not present in the Essential version.", targetMuscles: "Transversus abdominis, obliques and multifidus (anti-rotation), hip extensors and quadriceps of the supporting leg\nDevelopé also recruits the gesture leg's hip flexors eccentrically/concentrically as the knee extends and the leg lifts and lowers.", focus: "Same One Leg Bent, Bicycle and Single Heel positions as Essential, reversed breathing, plus a new fourth position (Developé) unique to the Intermediate repertoire.", positions: [
      { label: "One Leg Bent", detail: "Standard bent-knee press from a single-leg base; gesture leg holds tabletop." },
      { label: "Bicycle", detail: "Gesture leg cycles through a bicycle-pedal pattern (flexing into tabletop, extending over the footbar) opposite the supporting leg's press." },
      { label: "Developé", detail: "A.K.A. Développé. As the supporting leg presses out, the gesture leg flexes through tabletop and extends to reach the foot toward the ceiling — both legs extending simultaneously. Gesture leg then lowers toward the footbar and lifts back to the ceiling, then both ankles dorsiflex, then plantar flex, before the supporting leg returns and the gesture leg flexes back through tabletop to extend over the footbar. 5 reps per side." },
      { label: "Single Heel", detail: "Heel (instead of ball of foot) presses from the supporting leg while the gesture leg stays straight over the footbar." },
    ], modifications: ["Supporting ankle dorsiflexed (One Leg Bent).", "Laterally rotated / medially rotated supporting leg (One Leg Bent, Developé).", "Both ankles dorsiflexed (Bicycle).", "Flex the foot of the gesture leg to release hip flexor gripping (Developé, Single Heel).", "Flex the gesture leg (Single Heel)."] , script: { lines: ["Let's move into Single Leg. Same One Leg Bent, Bicycle, and Single Heel as before, breath reversed — inhale to press out, exhale to return — plus a new position, Developé.", "For Developé, as your supporting leg presses out, flex your gesture leg through tabletop and extend it to the ceiling. Lower it toward the footbar and lift it back up, then dorsiflex and plantar flex both ankles, before both legs return through their full cycle together.", "Keep your pelvis level and square throughout, especially as the gesture leg adds more movement — feel your transversus abdominis and obliques resisting rotation while your hip extensors and quadriceps do the pressing."] } },
    { name: "Hundred (Intermediate)", level: "Intermediate", page: "36–37", springs: "2–3", startingPosition: "Supine, imprinted position, legs in tabletop, elbows flexed by the sides, hands in straps.", pelvis: "Imprint", spine: "Upper thoracic flexion", breathing: "Staccato breathing, 5 counts in / 5 counts out, to 100 pumps — same as Essential.", targetMuscles: "Transversus abdominis, rectus abdominis, obliques, hip flexors, latissimus dorsi and pectoralis major, scapular stabilizers — same as Essential.", focus: "Manual header: \"Hundred — same as Essential.\" The only documented Intermediate-level change is the progression note below\nMovement, breathing rhythm and target muscles are otherwise identical to the Essential version.", notes: "NOTE: \"May be done starting in a neutral pelvic position and maintaining throughout, once strength is gained and ability demonstrated\" — the same optional neutral-pelvis progression noted for Coordination." , script: { lines: ["Let's move into Hundred. Same staccato pumping rhythm as before, five counts in, five counts out, up to a hundred.", "Once your strength and control are there, try starting and holding a neutral pelvis instead of imprint throughout.", "Keep your energy going out through your fingertips the entire time — your transversus and rectus abdominis hold the curl, your hip flexors keep your legs steady, and your latissimus dorsi and pectoralis major drive the pump."] } },
    { name: "Bend & Stretch (Intermediate)", level: "Intermediate", page: "38–39", springs: "2", startingPosition: "Supine, pelvis and spine neutral, footbar #1 or #4.\nFeet in straps, legs parallel and adducted, knees flexed, ankles dorsiflexed, per position below.", pelvis: "Neutral (imprint only if neutral cannot be maintained as the legs extend)", spine: "Neutral", breathing: "Exhale to extend the legs to the diagonal and point the feet\nInhale to flex the knees/hips and dorsiflex as the carriage returns.", targetMuscles: "Hip flexors, quadriceps, deep abdominals stabilizing the pelvis against the moving legs, adductors (Laterally/Medially Rotated).", focus: "Manual header: \"same as Essential except maintain Neutral.\" The Essential version starts in imprint and only returns toward neutral as the legs extend\nThe Intermediate version starts and stays in neutral pelvis throughout, imprinting only as a fallback if stability can't be maintained.", positions: [
      { label: "Parallel", detail: "Legs parallel and adducted, knees flexed, ankles dorsiflexed to start." },
      { label: "Laterally rotated", detail: "Heels together, toes apart, legs laterally rotated." },
      { label: "Medially rotated", detail: "Legs medially rotated, knees flexed and touching, toes remain touching as the knees come apart on extension." },
    ], notes: "NOTE (all positions): \"If stabilization cannot be maintained in neutral, imprint as legs extend.\"" , script: { lines: ["Let's move into Bend and Stretch. Same three rotations as before — parallel, turned out, turned in.", "This time, start and stay in neutral pelvis throughout, rather than starting in imprint.", "Only drop into imprint if you truly can't stabilize neutral as your legs extend — let your deep abdominals hold the pelvis steady while your hip flexors and quadriceps do the reaching."] } },
    { name: "Short Spine (Intermediate)", level: "Intermediate", page: "40–41", springs: "2", startingPosition: "Supine, pelvis and spine neutral, footbar #1 or #4, headrest flat.\nLegs straight, adducted and laterally rotated, on the diagonal as low as pelvic stability allows.\nFeet in straps, ankles plantar flexed, toes gently pointed.", pelvis: "Neutral (imprint if neutral can't be maintained as legs extend on the diagonal, returning toward neutral as the legs hinge toward the torso)", spine: "Full articulated flexion", breathing: "Inhale to rotate the legs parallel and hinge toward the torso, rolling the spine off the carriage\nA second inhale to flex the knees and laterally rotate at the top\nExhale to roll the spine down without moving the carriage\nFinal exhale to press the legs out.", targetMuscles: "Transversus abdominis, deep pelvic floor, gluteus maximus and hamstrings, rectus abdominis and obliques (spinal articulation), hip extensors/quadriceps/adductors on the press out, scapular stabilizers.", focus: "Manual header: \"same as Essential (Prep not in Intermediate).\" Only the full Short Spine carries into the Intermediate repertoire — Short Spine Prep is Essential-only.\nThe Intermediate version also starts in neutral pelvis rather than Essential's imprint start.", modifications: ["Peroneal stretch — bring the soles of the feet together as the knees flex at the top of the movement."] , script: { lines: ["Let's move into Short Spine. Come to supine, legs straight, turned out, on the diagonal, feet in the straps.", "Inhale to rotate your legs parallel and hinge toward your torso, rolling your spine off the carriage; exhale to roll back down without moving the carriage; then press your legs back out.", "Start this one in neutral pelvis rather than imprint — only fall back to imprint if you can't hold it. Your gluteus maximus and hamstrings drive the roll, your rectus abdominis and obliques control the articulation."] } },
    { name: "Beats", level: "Intermediate", page: "43", springs: "2", startingPosition: "Supine, pelvis and spine neutral (imprint if neutral can't be maintained).\nFeet in straps, heels together, toes apart, legs laterally rotated, knees flexed, ankles dorsiflexed.\nArms long by the sides.", pelvis: "Neutral (imprint if needed)", spine: "Neutral", breathing: "Exhale to extend the legs out to the diagonal (as low as pelvic stability allows)\nA quick breath to abduct then adduct the legs (\"beats\") at end range without moving the carriage\nInhale to flex the knees/hips and return.", targetMuscles: "Transversus abdominis, obliques (anti-extension), obliques and multifidus (anti-rotation), hip extensors, quadriceps, adductors, abductors.", focus: "Rapid, small-range abduction/adduction pulses of the straight legs at end range, while the pelvis and carriage stay completely still.", positions: [
      { label: "Three Beats", detail: "Open and close the legs three times quickly on one exhale — increases the muscular endurance demand." },
      { label: "Parallel", detail: "Maintain parallel leg alignment throughout, instead of the default lateral rotation." },
    ] , script: { lines: ["Let's move into Beats. Come to supine, feet in the straps, heels together, toes apart, legs turned out.", "Exhale to extend your legs out to the diagonal, then quickly open and close them — beats — at end range without moving the carriage. Inhale to bend your knees back in.", "Keep your pelvis and the carriage completely still while your legs pulse — the movement stays small and fast, working your abductors and adductors while your obliques and multifidus resist any rotation."] } },
    { name: "Frog", level: "Intermediate", page: "44–45", springs: "2", startingPosition: "Supine, pelvis and spine neutral.\nFeet in straps, ankles plantar-flexed, toes pointed.\nLegs straight, adducted, laterally rotated, extended on the diagonal as low as pelvic stability allows.\nArms long by the sides.", pelvis: "Neutral (imprint if needed)", spine: "Neutral", breathing: "Inhale to hinge the legs toward the torso without lifting the sacrum off the carriage\nExhale to flex the knees into a diamond/frog shape, then extend the knees to reach the feet out to the sides before re-adducting to press the carriage out.\nReverse for the second half of the set: inhale to dorsiflex and abduct the legs out to the sides to move the carriage in\nExhale to flex the knees drawing the feet together into the diamond, then extend the knees reaching to the ceiling and adduct before hinging the legs away again.", targetMuscles: "Adductors, hip extensors, quadriceps, deep abdominals stabilizing the pelvis.", focus: "The knees bend open into a frog/diamond shape then extend back out — hip abduction/adduction combined with knee flexion/extension while the carriage and pelvis stay still. Complete 5 repetitions in each direction.", notes: "Same diamond-shape leg sequence as the Arc Barrel Frog (p.44) and Spine Corrector Frog (p.52), performed inverted and without spring resistance on those apparatus." , script: { lines: ["Let's move into Frog. Come to supine, feet in the straps, legs straight, turned out, extended on the diagonal.", "Inhale to hinge your legs toward your torso without lifting your sacrum; exhale to bend your knees open into a diamond shape, then extend them back out to the sides before drawing them back together to press the carriage out. Then reverse the direction for the second half of the set.", "Keep the carriage and your pelvis completely still — the movement is all happening at your hips and knees, working your adductors and hip extensors both ways."] } },
    { name: "Stag", level: "Intermediate", page: "47", springs: "2", startingPosition: "Supine, pelvis and spine neutral.\nFeet in straps, ankles plantar-flexed, toes pointed.\nLegs straight, adducted, laterally rotated, extended on the diagonal as low as pelvic stability allows.\nArms long by the sides.", pelvis: "Neutral (imprint if needed)", spine: "Neutral", breathing: "Inhale: one leg abducts straight out to the side while the opposite knee flexes, dorsiflexes, and draws the heel toward the seat along the center line as the carriage moves in.\nExhale: the flexed knee extends and points as the abducted leg adducts back to center, moving the carriage out.\nAlternate sides.", targetMuscles: "Hip abductors/adductors, quadriceps, obliques and multifidus (anti-rotation), deep abdominals.", focus: "A.K.A.\nPas de Chat (\"Cat Step\") — asymmetrical leg work: one leg reaches out to the side while the other bends in, training each leg to control the carriage differently at the same time without the pelvis rocking or rotating." , script: { lines: ["Let's move into Stag. Come to supine, feet in the straps, legs straight, turned out, on the diagonal.", "Inhale as one leg opens out to the side while the other bends in, drawing the heel toward your seat; exhale as the bent knee extends and the open leg draws back to center.", "Keep your pelvis from rocking or rotating — each leg is doing something different at the same time, so your obliques and multifidus have to work hard to prevent rotation while your hip abductors and adductors control the legs."] } },
    { name: "Coordination", level: "Intermediate", page: "48", springs: "2", startingPosition: "Supine, imprinted, upper body flexed as in The Hundred, legs in tabletop.\nElbows flexed by the sides, humeri level with the shoulders, hands in straps.", pelvis: "Imprint (may progress to neutral once strength/control is established)", spine: "Thoracic flexion", breathing: "Inhale to extend the elbows level with the shoulders and simultaneously extend the legs onto the diagonal as low as imprint allows, moving the carriage out\nExhale to keep the legs straight and spine imprinted, carriage still, and abduct then adduct the legs (no wider than shoulder-distance)\nInhale to keep the upper body flexed and flex the knees back to tabletop\nExhale to keep the upper body flexed and flex the elbows to return the carriage.", targetMuscles: "Transversus abdominis, rectus abdominis, obliques (maintaining thoracic flexion and pelvic stability), triceps, hip flexors, abductors/adductors, scapular stabilizers, latissimus dorsi, pectoralis major.", focus: "A.K.A. \"combination of 100 + Beats.\" Combines the arm-pumping pattern of The Hundred with the leg beats of Beats — a full-body coordination and endurance challenge for the upper-body-flexed abdominal position." , script: { lines: ["Let's move into Coordination. Come to supine, imprinted, upper body flexed as in Hundred, legs in tabletop, elbows by your sides.", "Inhale to extend your arms and legs together, out to the diagonal; exhale to open and close your legs without moving the carriage; inhale to bend your knees back to tabletop; exhale to bend your elbows and return.", "Keep your pelvis anchored and still the entire time your arms and legs are moving — coordinate the breath with the reach, don't rush it. Your transversus and rectus abdominis hold the flexion, your triceps extend the elbows, and your hip flexors and adductors/abductors control the legs."] } },
    { name: "Back Rowing", level: "Intermediate", page: "50–53", springs: "1–2", startingPosition: "Seated facing the back of the Reformer, straps in the hands, progressing from the Essential Back Rowing Preps (page 49).", pelvis: "Neutral (Round Back: posterior tilt during the roll-down)", spine: "Neutral to flexion (Round Back)", breathing: "Inhale to prepare/reach\nExhale to row.", targetMuscles: "Rhomboids, mid trapezius, posterior deltoid, biceps/triceps, deep abdominals (Round Back roll-down).", focus: "Builds on the Essential Back Rowing Preps into two fuller seated sequences.\nNOTE: to achieve full range of motion, straps can be shortened or changed to foam grip handles, and the carriage stopper can be moved to position #2 for all Back Rowing.", positions: [
      { label: "Round Back", detail: "Roll the pelvis away from the femurs into a flexed C-curve while pulling the hands to the sternum, extend the arms out to the sides, press the arms back behind the shoulders while flexing the torso further forward over the legs, then circle the arms up/out and forward to return, sequentially lengthening the spine back to sitting." },
      { label: "Straight Back", detail: "Hinge the pelvis away from the femurs on a long neutral spine while drawing the hands to the ears, extend the arms overhead as the pelvis hinges back toward the femurs, then flex the spine forward over the legs pressing the hands down and back, circling the arms forward to return and lengthening back to sitting." },
    ] , script: { lines: ["Let's move into Back Rowing. Come to seated, facing the back of the Reformer, straps in your hands.", "Inhale to prepare and reach; exhale to row. We'll work through Round Back, then Straight Back.", "Keep both arms working equally and at the same pace — the resistance is independent on each side, so it's easy for one to take over. Feel your rhomboids, mid trapezius and posterior deltoids rowing, with your deep abdominals controlling the roll-down in Round Back."] } },
    { name: "Front Rowing — Intermediate Set", level: "Intermediate", page: "55–61", springs: "1–2", startingPosition: "Seated upright facing the footbar, sitting against the shoulder rests, legs straight and adducted, ankles plantar flexed, per position below.", pelvis: "Neutral", spine: "Neutral, elongated (or articulated flexion in Round Forward with Arm Circles)", breathing: "Inhale to prepare/press\nExhale to row/press — pattern varies by position (see individual positions).", targetMuscles: "Anterior/medial/posterior deltoids, pectoralis major, triceps, erector spinae, rectus abdominis and obliques, scapular stabilizers.", focus: "Builds on the Essential Front Rowing Preps (Arm Circles progresses from Straight Forward p.64) with two new Intermediate positions, then finishes with a choice of the Essential Second Position or Offering pattern.", positions: [
      { label: "Arm Circles", detail: "Press the hands forward to eye level extending the elbows, medially rotate the arms and lower them forward, laterally rotate and raise the arms overhead, then circle out to the sides and down to return — one continuous circle timed with the breath." },
      { label: "Round Forward with Arm Circles", detail: "Same arm-circle pattern, performed while the spine sequentially articulates up from a flexed, rounded-forward position to neutral sitting, then flexes back down." },
      { label: "Salute", detail: "Hinge forward from the pelvis on a stable spine with the hands forming a diamond behind the head; press the hands into the straps extending the elbows along the diagonal line of the body, then flex the elbows to return." },
      { label: "Second Position / Offering", detail: "Choose one: Second Position — arms abducted at shoulder height, palms forward, press forward and together in a horizontal-adduction arc (same as Essential Front Rowing Preps, p.65). Offering — elbows flexed and slightly behind the body, palms up; extend the elbows forward at shoulder level, then horizontally abduct and adduct the straight arms before flexing to return (same as Essential Front Rowing Preps, p.60)." },
    ] , script: { lines: ["Let's move into Front Rowing. Come to seated tall, facing the footbar, legs straight and together.", "Inhale to prepare; exhale to row or press. We'll move through Arm Circles, Round Forward with Arm Circles, Salute, then finish with Second Position or Offering.", "Sit tall through your whole spine before you row — draw your shoulder blades down as your arms move, feeling your deltoids and pectoralis major press while your erector spinae keeps you tall."] } },
    { name: "Stomach Massage — Intermediate", level: "Intermediate", page: "63–67", springs: "2–3", startingPosition: "Seated, weight back of the sit-bones, on the gripper mat in the center of the carriage, footbar #1 (lower to #2 if hip tightness causes discomfort).\nLegs laterally rotated, knees flexed, balls of the feet on the footbar, heels together, toes apart.", pelvis: "Posterior tilt (Round Back) or neutral (Straight Back, Reaching, Twist)", spine: "Flexion, C-curve (Round Back) or lengthened thoracic spine (Straight Back, Reaching, Twist)", breathing: "Inhale to extend the knees and press the carriage out (lifting the heels, then lowering and lifting them)\nExhale to flex the knees and return.", targetMuscles: "Deep abdominals, mid-back erector spinae (Straight Back/Reaching/Twist), hip extensors/quadriceps/adductors, gastrocnemius and soleus (heel lower-and-lift), psoas, external/internal obliques (Twist, to rotate the spine).", focus: "Extends the Essential Round Back/Straight Back pair with two further Intermediate positions — Reaching (arms overhead) and Twist (spinal rotation) — each performed with the same heel lower-and-lift leg press.", positions: [
      { label: "Round Back", detail: "Spine flexed in a C-curve ('spoon' shape), hands tucked under the thighs or lightly pressing the sides of the carriage." },
      { label: "Straight Back", detail: "Lumbar in slight flexion, thoracic lengthened tall; hands lightly on top of or beside the shoulder rests, elbows pointing back." },
      { label: "Reaching", detail: "Same tall Straight Back torso, arms straight and reaching toward the ceiling as high as scapular stabilization allows, palms facing in — torso stabilizers work harder here than Straight Back because of the longer arm lever." },
      { label: "Twist", detail: "Arms rounded in front of the body at shoulder height; as the carriage presses out, rotate the spine to one side reaching one arm forward and one back, keeping the pelvis square, then rotate back to center as the carriage returns. 5 reps each way, alternating." },
    ], modifications: ["Omit the lower and lift, pressing on 2 breaths instead of 4 (all positions).", "Spine in C-curve to start Twist, lengthening to Straight Back as the spine rotates — a harder coordination challenge."] , script: { lines: ["Let's move into Stomach Massage. Come to seated, weight just behind your sit-bones, legs turned out, balls of your feet on the bar.", "Inhale to extend your knees and press the carriage out, lowering then lifting your heels; exhale to bend your knees and return. We'll move through Round Back, Straight Back, Reaching, then Twist.", "Keep your torso tall and lengthened in the upright positions — the heel lower-and-lift challenges your gastrocnemius and soleus, while your deep abdominals and mid-back erector spinae hold you steady, and your obliques rotate you in Twist."] } },
    { name: "Arms Pulling Straps — Long Box (Intermediate)", level: "Intermediate", page: "68–70", springs: "1", startingPosition: "Prone on the long box, head toward the pulleys, pelvis neutral, upper body and head relaxed off the end of the box, legs straight and parallel to the floor.", pelvis: "Neutral", spine: "Extension", breathing: "Same movement as Essential, but combined into two breaths instead of four for a smoother action: inhale to slide the scapulae down and pull the arms all the way back to hip level (moving into thoracic extension)\nExhale to reach the arms back toward the floor/forward and fully return the carriage.", targetMuscles: "Rhomboids, posterior deltoid, triceps, mid/upper erector spinae, latissimus dorsi and teres major, scapular stabilizers.", focus: "Manual header: \"Same as Essential (72) Except Breathing changed.\" NOTE: \"Plow and Airplane are done with two breaths at intermediate level.\nMovement exactly as in essential level.\"", positions: [
      { label: "Plow", detail: "A.K.A. Pulling Straps Down to Floor. Arms reach down by the sides of the carriage and forward, palms in; pull the arms down and back to hip level as the spine extends." },
      { label: "Airplane", detail: "A.K.A. Pulling Straps Out to Sides. Arms reach out to the sides at shoulder level and forward, palms down; pull the arms back to the hips as the spine extends." },
      { label: "Triceps", detail: "Elbows flexed by the waist, palms in; extend the elbows only (humeri and torso stay still), then flex to return." },
    ] , script: { lines: ["Let's move into Arms Pulling Straps on the Long Box. Come to prone, head toward the pulleys, legs straight and parallel.", "Inhale to slide your shoulder blades down and pull your arms all the way back to hip level, moving into extension; exhale to reach your arms back toward the floor or forward and fully return the carriage.", "This is the same pattern as before, just combined into two breaths instead of four — keep it smooth. Your rhomboids and posterior deltoids pull, your latissimus dorsi and teres major stabilize, and your mid-back erector spinae holds the extension."] } },
    { name: "Backstroke Prep — Long Box", level: "Intermediate", page: "71", springs: "2", startingPosition: "Supine on the long box, head toward the pulleys, imprinted position, upper body flexed, legs in tabletop, arms held out to the sides slightly rounded just above shoulder level, hands in straps, palms facing the body.", pelvis: "Imprint (may progress to neutral once strength/control is established)", spine: "Thoracic flexion", breathing: "Exhale to maintain spinal flexion and pull the arms in toward the hips, moving the carriage out\nInhale to open the arms back to starting position, controlling the return.", targetMuscles: "Transversus abdominis, rectus abdominis and obliques (isometric, thoracic flexion and pelvic stability), latissimus dorsi, teres major and pectoralis major (arm adduction), scapular stabilizers.", focus: "A Hundred-position arm-adduction pattern on the long box\nNOTE: may be done in a neutral position once strength is gained and ability demonstrated." , script: { lines: ["Let's move into Backstroke Prep on the Long Box. Come to supine, imprinted, upper body flexed, legs in tabletop, arms out to the sides holding the straps.", "Exhale to pull your arms in toward your hips, moving the carriage out, while holding your flexion; inhale to open your arms back out, controlling the return.", "Keep your thoracic flexion and pelvic stability steady the whole time your arms are moving — that's your transversus and rectus abdominis holding you, while your latissimus dorsi and pectoralis major pull the arms in."] } },
    { name: "Feet Pulling Straps — Long Box", level: "Intermediate", page: "72–76", springs: "1", startingPosition: "Prone or side-lying on the long box, feet or ankle in the strap instead of the hands, per position below.", pelvis: "Neutral", spine: "Neutral (or slight extension in Hamstring Curls)", breathing: "Inhale to prepare\nExhale to move the carriage out with the leg action described per position\nInhale to return.", targetMuscles: "Hamstrings and gluteus maximus (Hamstring Curls, Kneeling One Leg Pull, Side-Lying One Leg Pull — hip extension), gluteus medius and lateral rotators (Knee Lift — horizontal abduction), transversus abdominis, obliques and multifidus (anti-rotation) throughout.", focus: "Four prone/side-lying leg-pulling patterns building posterior-chain and lateral hip strength on the long box.", positions: [
      { label: "Hamstring Curls", detail: "A.K.A. Feet Pulling Straps. Prone, kneecaps just off the back edge of the box, legs laterally rotated, knees apart and heels together, feet in the straps; flex the knees pulling the heels toward the seat to move the carriage out, then return." },
      { label: "Kneeling One Leg Pull", detail: "On hands and one supporting knee on the box, gesture leg straight with the foot in the strap; pull the gesture leg straight back to extend the hip, moving the carriage out, then flex the hip to return." },
      { label: "Knee Lift", detail: "Side-lying on the box, hips and knees flexed to 90°, strap around the top knee; horizontally abduct the top leg (\"like a book opening\") from the hip to move the carriage out, then adduct to return." },
      { label: "Side-Lying One Leg Pull", detail: "Side-lying on the box, top leg straight and parallel at hip height with the foot in the strap; pull the top leg straight back to extend the hip, moving the carriage out, then return." },
    ], modifications: ["Legs parallel and adducted (Hamstring Curls) — emphasizes adductors/medial hamstrings.", "Hands placed on the carriage instead of under the forehead (Hamstring Curls) — easier to stabilize neutral spine.", "Straps around the ankles to reduce cramping (Hamstring Curls).", "Gesture leg laterally rotated (Kneeling One Leg Pull, Side-Lying One Leg Pull) — more lateral hamstring/rotator emphasis.", "Keep the toes together (Knee Lift) — intensifies the lateral rotators."] , script: { lines: ["Let's move into Feet Pulling Straps on the Long Box. We'll work through four patterns — Hamstring Curls prone, Kneeling One Leg Pull, side-lying Knee Lift, then side-lying One Leg Pull.", "Inhale to prepare; exhale to move the carriage out with the leg action for each position; inhale to return.", "Keep your pelvis stable and resist any rotation — your transversus abdominis and obliques hold you steady while your hamstrings and gluteus maximus (or gluteus medius in Knee Lift) do the leg work."] } },
    { name: "Round Back — Short Box (Intermediate)", level: "Intermediate", page: "78", springs: "2", startingPosition: "Seated upright on the box, pelvis and spine neutral, legs adducted with feet hooked under the footstrap, each hand holding the opposite wrist in front of the lower abdomen.", pelvis: "Neutral to posterior tilt during the roll-down", spine: "Flexion", breathing: "Exhale to roll the pelvis away from the femurs into lumbar flexion\nInhale to lift the stabilized arms overhead\nExhale to flex the torso forward over the legs with the arms staying overhead\nInhale to sequentially lengthen the spine back to neutral.", targetMuscles: "Deep abdominals, gluteus maximus and hamstrings (roll-back), scapular stabilizers.", focus: "Manual header: \"Same as Essential, except Pic 3 is different (76).\" In the Essential version the arms lower to eye level before the torso flexes forward\nIn the Intermediate version the arms stay reaching overhead throughout the forward flexion." , script: { lines: ["Let's move into Round Back on the Short Box. Come to seated, legs together, feet under the strap, hands holding your opposite wrist in front of your abdomen.", "Exhale to roll your pelvis back into flexion; inhale to lift your arms overhead; exhale to flex forward over your legs, keeping your arms reaching overhead; inhale to sequentially roll back up.", "Keep your arms reaching overhead through the whole forward fold this time, rather than lowering them — let your deep abdominals initiate the roll while your gluteus maximus and hamstrings bring the pelvis back to the femurs."] } },
    { name: "Straight Back — Short Box (Intermediate)", level: "Intermediate", page: "79", springs: "2", startingPosition: "Seated upright on the box, pelvis and spine neutral, legs adducted with feet hooked under the footstrap, arms straight shoulder-distance apart holding a pole overhead.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Exhale to hinge the pelvis away from the femurs on a stable spine, hinging only as far as neutral spine can be maintained\nInhale to hold at the hinged position\nExhale to return to vertical, weight directly on the sit-bones.", targetMuscles: "Deep abdominals (isometric), erector spinae, obliques, scapular stabilizers.", focus: "Manual header: \"Same as Essential (77)\" — the Intermediate write-up documents no difference from the Essential Straight Back Short Box\nIt is simply re-listed for review at Intermediate level.", notes: "NOTE: If neutral spine cannot be stabilized during the hinge back, imprint slightly and return to neutral as the torso returns to vertical." , script: { lines: ["Let's move into Straight Back on the Short Box. Come to seated, legs together, feet under the strap, arms straight holding a pole overhead.", "Exhale to hinge back on a stable spine, only as far as you can hold neutral; inhale to hold; exhale to return to vertical, weight directly on your sit-bones.", "If you can't hold neutral through the hinge, imprint slightly rather than losing your form — your erector spinae, obliques and deep abdominals are all working isometrically to keep the spine still."] } },
    { name: "Twist with Round Back — Short Box", level: "Intermediate", page: "80–81", springs: "2", startingPosition: "Seated upright on the box, pelvis and spine neutral, legs adducted with feet hooked under the footstrap, arms straight shoulder-distance apart holding a pole overhead.", pelvis: "Posterior tilt during the roll-down; square to the front during rotation", spine: "Flexion with rotation", breathing: "Exhale to roll into lumbar flexion lowering the pole to shoulder level\nInhale to lift the pole overhead\nExhale to rotate the torso to one side (pole parallel to the floor)\nInhale to rotate back to center\nRepeat to the other side\nExhale to flex forward over the legs\nInhale to roll back up to sitting.", targetMuscles: "External oblique on one side and internal oblique on the opposite side (rotation), rectus abdominis and obliques (flexion), gluteus maximus and hamstrings, scapular stabilizers.", focus: "Combines the Round Back roll-down with axial rotation held on a parallel pole — a full-sequence combination of Round Back and Twist.\nComplete 3 repetitions each way, alternating." , script: { lines: ["Let's move into Twist with Round Back on the Short Box. Come to seated, legs together, feet under the strap, holding a pole overhead.", "Exhale to roll into flexion, lowering the pole to shoulder height; inhale to lift the pole overhead; exhale to rotate to one side; inhale to rotate back to center; repeat to the other side; then exhale to fold forward over your legs and inhale to roll back up.", "Keep the pole level and your pelvis square as you rotate — this combines the roll-down with a full twist, using your obliques on both sides to rotate while your gluteus maximus and hamstrings control the pelvis."] } },
    { name: "Lean", level: "Intermediate", page: "82", springs: "2", startingPosition: "Sitting tall on the short box, facing the platform, feet hooked under the foot strap, holding a wooden pole overhead shoulder-distance apart.", pelvis: "Neutral, square to the front", spine: "Rotation then lateral lean, kept rigid", breathing: "Inhale to rotate the upper torso to one side, pelvis square to the front\nExhale to lean diagonally back and to the side, keeping both sides of the torso equally long\nInhale to return to vertical, keeping the same rotation\nExhale to rotate the torso back to center. Repeat to the other side.", targetMuscles: "Deep abdominals (isometric), obliques, hip flexors (anchoring).", focus: "Combines the Straight Back hip-hinge (p.77) with Twist (p.79) — the torso leans back as one rigid, rotated unit, hinging only at the hip.", cues: ["Imagine your spine is a solid iron rod that cannot bend as you lean diagonally back — think of your hips as a heavy door hinge, with the whole torso moving like the door itself.", "Picture headlights on your collarbones, shining straight up and never dropping toward your knees.", "Picture your sit bones bolted into the box as an anchor, and a wide seatbelt tightening across your lower abs as you lean away."] , script: { lines: ["Let's move into Lean. Come to sitting tall on the short box, feet under the strap, holding a pole overhead.", "Inhale to rotate your torso to one side; exhale to lean diagonally back and to the side; inhale to return to vertical, keeping the rotation; exhale to rotate back to center.", "Keep your spine rigid as one solid piece — the lean happens only at your hips, like a hinge, not by bending your back. Your deep abdominals and obliques hold the rigidity while your hip flexors anchor you."] } },
    { name: "Tree — Short Box (Intermediate)", level: "Intermediate", page: "84–85", springs: "2", startingPosition: "Seated upright on the box, pelvis square to the front, one foot hooked under the footstrap, other leg flexed with the inside hand under the knee and the outside hand reaching the ankle.", pelvis: "Neutral to posterior tilt during the roll back", spine: "Articulated flexion into full extension", breathing: "Exhale to extend the gesture knee (repeat 3 times)\nOn the last rep\nInhale\nExhale to roll the pelvis into lumbar flexion and walk the hands down the leg, continuing to roll the spine into full extension over the back of the box\nInhale to flex from the head and roll back up to sitting.", targetMuscles: "Quadriceps of the gesture leg, hip flexors of the supporting leg, rectus abdominis and obliques, multifidus (anti-rotation).", focus: "Manual header: \"Same as Essential, except Pic 4, roll into extension.\" The Essential version (listed here as modification 2, \"Essential version\") rolls only halfway back, stopping once the sacrum area contacts the box\nThe Intermediate version continues rolling the spine all the way into full supported extension over the back of the box.\nNOTE: a trained professional must spot throughout in case support is needed.", modifications: ["Omit the roll back — hamstring stretch only.", "Essential version — roll only halfway back to develop abdominal strength for the full version.", "Flex the top knee during roll back if hamstrings restrict movement.", "Reach the arms back to hold the rails once in extension, to challenge pelvis/spine stability."] , script: { lines: ["Let's move into Tree on the Short Box. Come to seated, one foot under the strap, other leg extended, hands on your shin and ankle.", "Exhale to extend your gesture knee three times; then roll your pelvis back into flexion and walk your hands down your leg, continuing to roll your spine all the way into extension over the back of the box; inhale to roll back up to sitting.", "This time roll all the way into full extension rather than stopping halfway — control the movement the entire way, using your rectus abdominis and obliques to control the roll while your gesture leg's quadriceps hold the extension."] } },
    { name: "Mermaid — Short Box", level: "Intermediate", page: "86–90", springs: "2", startingPosition: "Seated on the box facing sideways, pelvis and spine neutral, leg nearest the footbar long and laterally rotated with the foot hooked under the footstrap, opposite knee and hip flexed with the foot on the box, per position below.", pelvis: "Neutral", spine: "Lateral flexion (with rotation in Hawk)", breathing: "Inhale to reach/lean into the diagonal\nExhale to laterally flex\nPattern varies by position (see individual positions).", targetMuscles: "Internal and external obliques of the side closest to the footbar, obliques and multifidus (anti-rotation), obliques and erector spinae (anti-flexion/extension), scapular stabilizers.", focus: "Three named lateral-flexion positions on the short box, each reaching into a diagonal line before flexing laterally toward the footbar or shoulder rests.", positions: [
      { label: "Side Bend", detail: "Lean away from the footbar into a full diagonal (hip nearest the footbar lifts off the box), top arm overhead and bottom arm curved around the bottom knee; laterally flex toward the floor then return to vertical, then repeat flexing toward the footbar with the arms swapped." },
      { label: "Hawk", detail: "Same diagonal lean and reach, but on the exhale the upper torso flexes and rotates to face the floor with the arms reaching out to the sides, palms down, before returning to the diagonal and laterally flexing toward the footbar." },
      { label: "Bow & Arrow", detail: "Bottom hip rests on the box in a long diagonal from feet to head; top leg straight with the foot hooked under the footstrap, bottom foot hooked behind the top ankle, bottom arm wrapped around the waist, top arm overhead; laterally flex toward the floor and return, without rotation. Breath is reversed from Side Bend/Hawk here — inhale to laterally flex toward the floor, exhale to lengthen from tail to head and return to the diagonal line." },
    ], modifications: ["Rest pulleys hanging off the side of the box, to reduce discomfort while keeping a square, neutral pelvis (Side Bend, Hawk)."] , script: { lines: ["Let's move into Mermaid on the Short Box. Come to seated sideways, one leg long and turned out with the foot hooked under the strap, other knee bent with the foot on the box.", "For Side Bend and Hawk, inhale to reach and lean into the diagonal, exhale to laterally flex. For Bow and Arrow the breath flips — inhale to laterally flex toward the floor, exhale to lengthen back to the diagonal.", "Lengthen your whole spine into the diagonal before you flex sideways — the reach comes first, working the obliques on the footbar side while your erector spinae controls the flexion and extension."] } },
    { name: "Long Stretch", level: "Intermediate", page: "92–93", springs: "1–2", startingPosition: "Push-up (dart) position, hands on the footbar shoulder-distance apart, balls of the feet at the crease of the fully-raised headrest, one long line from feet to head.", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale to flex the shoulders and press the carriage out as far as torso/scapular stabilization allows\nExhale to extend the shoulders and return (the carriage does not have to return fully).", targetMuscles: "Deep abdominals, hip extensors and adductors (pelvic stability), scapular stabilizers with emphasis on serratus anterior, pectoralis major and anterior deltoids.", focus: "A full dart-position plank carriage press — core and shoulder stability under a large range of motion.", modifications: ["Prep on knees — knees flexed and on the carriage instead of straight legs, isolating the same shoulder-joint movement."] , script: { lines: ["Let's move into Long Stretch. Come to a push-up position, hands on the footbar, one long line from your feet to your head.", "Inhale to press the carriage out as far as you can hold your torso stable; exhale to return.", "Keep one long stable line from your heels to your head — resist letting your hips pike or sag. Your deep abdominals and hip extensors hold the line, your pectoralis major and anterior deltoids do the pressing."] } },
    { name: "Down Stretch", level: "Intermediate", page: "94–95", springs: "1–2", startingPosition: "Kneeling on the carriage, feet against the shoulder rests, hands holding the footbar, spine flexed, weight sitting back toward the heels.", pelvis: "Posterior tilt to neutral as the bow shape forms", spine: "Flexion to extension (bow/swan-dive shape)", breathing: "Inhale to stay\nExhale to lengthen the spine to neutral and press the legs back, bringing the hips then spine into a supported bow/banana shape, moving the carriage out\nThen, holding the bow shape: exhale to extend the shoulder joint and move the carriage in, reaching the chest toward the ceiling\nInhale to flex the shoulder joint and press the carriage back out (repeat this in/out pulse 3 times)\nTo finish: exhale to flex the hips, knees and spine together to return the carriage and starting position.", targetMuscles: "Hip extensors and erector spinae (extended position), obliques (prevent over-extension), pectoralis major and anterior deltoids, scapular stabilizers.", focus: "A.K.A. related to the Essential/Intermediate Swan Dive family — builds a supported \"bow\" shape through the whole body from a kneeling flexed start.\nComplete 2 sets of the entire sequence." , script: { lines: ["Let's move into Down Stretch. Come to kneeling on the carriage, feet against the shoulder rests, hands on the footbar, spine flexed.", "Exhale to lengthen your spine to neutral and press your legs back into a supported bow shape, moving the carriage out. Then, holding that bow shape, exhale to bring the carriage in reaching your chest toward the ceiling, inhale to press it back out — three times — before exhaling to flex hips, knees and spine together to return.", "Build one long supported curve through your whole body and hold it steady through the pulses — don't let your low back do all the work. Your hip extensors and erector spinae hold the bow, your obliques prevent over-extending, and your pectoralis major and anterior deltoids drive the pulse."] } },
    { name: "Up Stretch", level: "Intermediate", page: "96–97", springs: "1–2", startingPosition: "Standing on the carriage, feet against the shoulder rests, hands holding the footbar, spine flexed with the pelvis over the feet as much as possible.", pelvis: "Posterior tilt to neutral (dart) then flexion on return", spine: "Flexion into a dart (neutral) position, then re-flexion", breathing: "Inhale to extend the hips and press the carriage out, then lengthen from the tail into a neutral dart position\nExhale to extend the shoulders bringing the shoulders over the hands and start returning the carriage, then flex the spine from the head down and pull the feet back underneath the pelvis to finish the return.", targetMuscles: "Hip extensors, rectus abdominis and obliques, erector spinae, pectoralis major and anterior deltoids, latissimus dorsi and posterior deltoid, hip flexors, scapular stabilizers.", focus: "Manual note: \"combine Elephant + Round Back\" — pairs the standing Elephant hip-press with the dart/plank shoulder work of Long Stretch.", modifications: ["On four breaths — separate breaths for extending the hips, lengthening into the dart, bringing the shoulders over the hands, and flexing to return, to learn the coordination sequence."] , script: { lines: ["Let's move into Up Stretch. Come to standing on the carriage, feet against the shoulder rests, hands on the footbar, spine flexed.", "Inhale to extend your hips and press the carriage out, then lengthen into a neutral dart position; exhale to bring your shoulders over your hands as the carriage returns, then flex your spine and pull your feet back underneath you to finish.", "Think of this as combining Elephant's hip press with Long Stretch's plank — coordinate the sequence rather than rushing it. Your hip extensors and rectus abdominis power the press, your pectoralis major, anterior deltoids and latissimus dorsi carry the plank."] } },
    { name: "Elephant (Intermediate)", level: "Intermediate", page: "98–99", springs: "1–2", startingPosition: "Standing on the carriage, feet against the shoulder rests, hands holding the footbar, per position below.", pelvis: "Posterior tilt (Round Back) or neutral, imprinted slightly if needed (Straight Back)", spine: "Flexion (Round Back) or as neutral as possible (Straight Back)", breathing: "Inhale to extend the hips and press the carriage out\nExhale to flex the hips and pull the feet back under the pelvis, returning the carriage.", targetMuscles: "Rectus abdominis and obliques (Round Back, isometric flexion) or obliques and erector spinae (Straight Back), hip extensors concentrically on press, hip flexors concentrically on return, scapular stabilizers.", focus: "Manual header: \"Same as Essential\" for both positions — re-lists the Essential Round Back / Straight Back Elephant for Intermediate level with no documented movement change.", positions: [
      { label: "Round Back", detail: "Ankles dorsiflexed, spine flexed with the pelvis drawn over the feet." },
      { label: "Straight Back", detail: "A.K.A. Flat Back. Ankles dorsiflexed, spine as neutral/long as possible (imprint slightly if hamstrings restrict neutral)." },
    ], modifications: ["Move the feet forward on the carriage — ideal for shorter torso lengths (both positions).", "High half-toe, standing on the balls of the feet — reduces hamstring tension (Straight Back)."] , script: { lines: ["Let's move into Elephant. Come to standing on the carriage, feet against the shoulder rests, hands on the footbar.", "Exhale to draw the carriage in; inhale to let it glide back out. We'll work through Round Back, then Straight Back.", "Same pattern as before — hinge from your hips and keep the stretch in your hamstrings, not your low back."] } },
    { name: "Semicircle", level: "Intermediate", page: "100–101", springs: "2", startingPosition: "Upper thoracic and head on the carriage, arms overhead braced against the shoulder rests, balls of the feet on the footbar, heels together, toes apart, legs slightly laterally rotated, hips extended to lift the pelvis over the feet, carriage in toward the footbar as much as possible.", pelvis: "Neutral, lifted (bridge) at the start", spine: "Articulated flexion into extension and back", breathing: "Inhale to extend the knees and press the carriage out, then articulate the spine from thoracic to tail, lowering the pelvis between the springs\nExhale to flex the knees and return the carriage, articulating tail to thoracic to lift the pelvis back over the feet.\nReverse direction for the second half of the set.", targetMuscles: "Rectus abdominis and obliques (spinal roll), gluteus maximus and hamstrings (hip extension, carriage press with pelvis lifted), quadriceps, scapular stabilizers.", focus: "A bigger, more demanding combination of a bridge hold with spinal articulation and a carriage press — the hardest of the Hip Lift/Hip Rolls family.\nComplete 3 repetitions in each direction.", modifications: ["On four breaths, exhaling on the spinal articulation, to learn the coordination sequence.", "Don't extend the knees fully — allow slight knee flexion so the spine rolls up and down more easily."] , script: { lines: ["Let's move into Semicircle. Come to your upper back and head on the carriage, arms braced overhead against the shoulder rests, balls of your feet on the bar, hips lifted into a bridge.", "Inhale to extend your knees and press the carriage out, then articulate your spine down from your upper back to your tailbone, lowering your hips; exhale to bend your knees and return, articulating back up to lift your hips over your feet.", "Lift your hips up and over into one long extended line — feel your whole spine lengthen through this one."] } },
    { name: "Chest Expansion", level: "Intermediate", page: "103–104", springs: "1–2", startingPosition: "Kneeling on the carriage, thighs against the shoulder rests, facing the pulleys, femurs vertical, spine and pelvis neutral, arms straight holding the ropes in fists, palms facing in, reaching forward as far as scapular stabilization allows.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Exhale to pull the arms back extending the shoulders\nInhale to hold and turn the head to one side then the other (Chest Expansion) or pulse the arms back for 3 counts (Pulses)\nInhale/exhale to return.", targetMuscles: "Latissimus dorsi, rhomboids, posterior deltoid, gluteus maximus and hamstrings (pelvis on femurs), obliques and erector spinae, deep neck rotators (Chest Expansion), scapular stabilizers (trapezius and rhomboids).", focus: "A kneeling isometric-torso, moving-arm pattern in two variations: one that adds cervical rotation with a stable spine, one that adds pulsing presses at end range.\nNOTE: a trained professional must spot throughout in case balance is lost.", positions: [
      { label: "Chest Expansion", detail: "Pull the arms back to end range, hold, and turn the head to one side then the other before returning the head to center and the arms forward. 6 reps, alternating the head-turn side." },
      { label: "Pulses", detail: "Pull the arms back to end range, release slightly back to hip level, then press the arms back for three separate pulsing counts, each reaching further, before returning. 6 reps." },
    ], modifications: ["Palms facing back.", "Palms facing front.", "Move away from the shoulder rests — knees positioned so the ankles are at the edge of the carriage, increasing the stability demand."] , script: { lines: ["Let's move into Chest Expansion. Come to kneeling on the carriage, thighs against the shoulder rests, arms straight holding the ropes.", "Exhale to pull your arms back, extending your shoulders; hold and turn your head to one side then the other, or pulse your arms back for three counts; inhale to return.", "Draw your shoulder blades down and together before you press, and keep growing taller through your spine with every rep. Feel your latissimus dorsi, rhomboids and posterior deltoids doing the pull, while your gluteus maximus and hamstrings keep your pelvis anchored on your femurs."] } },
    { name: "Side Arm Preps — Kneeling", level: "Intermediate", page: "106–113", springs: "0.25–2", startingPosition: "Kneel on the carriage facing sideways, knees hip-distance apart, femurs vertical, spine and pelvis neutral, one hand holding a strap, other hand gently pressing the side of the thigh, per position below.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Exhale to move the carriage out with the arm action described per position\nInhale to return.", targetMuscles: "Rotator cuff (subscapularis for Internal Rotation; infraspinatus/teres minor for External Rotation), latissimus dorsi and pectoralis major (Adduction, Long Arm Adduction), deltoid and supraspinatus (Abduction, Long Arm Abduction, Backhand), triceps (Backhand elbow extension), obliques and erector spinae (torso stability), scapular stabilizers.", focus: "Manual header: \"Similar to Essential Side Arm Preps Sitting (58)\" — same rotator-cuff/shoulder patterns as the Essential seated version, but from a kneeling base (removing the stability of sitting) and extended from 4 to 7 named positions.\nESSENCE bracket confirms [EXERCISES 1-7].", positions: [
      { label: "Internal Rotation", detail: "Forearm across the front of the torso, elbow flexed 90°; internally rotate the humerus at the shoulder to move the carriage out." },
      { label: "External Rotation", detail: "Forearm across the front of the torso, elbow flexed 90°, hand toward the footbar side; externally rotate the humerus to move the carriage out." },
      { label: "Adduction", detail: "Elbow flexed 90° with the shoulder abducted toward the pulleys; adduct the humerus, pulling the forearm across the front of the torso, to move the carriage out." },
      { label: "Abduction", detail: "Elbow flexed 90°, forearm across the front of the torso; abduct the humerus away from the torso, elbow staying flexed, to move the carriage out." },
      { label: "Long Arm Adduction", detail: "Arm straight and abducted away from the torso, kneeling away from the shoulder rests; adduct the straight arm in toward the torso to move the carriage out — longer lever than Adduction." },
      { label: "Long Arm Abduction", detail: "Arm straight close to the side of the torso; abduct the straight arm away from the torso to move the carriage out — longer lever than Abduction." },
      { label: "Backhand", detail: "Elbow flexed, forearm across the front of the torso; abduct the humerus (elbow flexed) to start the carriage out, then extend the elbow in a flowing motion so the forearm continues on a diagonal up and out; reverse to return." },
    ], modifications: ["Palm facing up / palm facing down (all rotation positions).", "Short strap to increase difficulty (External Rotation).", "On four breaths, separating the abduction and elbow-extension phases (Backhand).", "Rotating upper torso — begin rotated toward the pulleys and rotate away as the arm abducts (Backhand)."] , script: { lines: ["Let's move into Side Arm Preps, Kneeling. Come to kneeling sideways on the carriage, one hand holding a strap, other hand resting on your thigh.", "Exhale to move the carriage out with each arm action; inhale to return. We'll move through internal rotation, external rotation, adduction, abduction, then the long-arm versions of adduction and abduction, finishing with Backhand.", "Keep your torso tall and completely still — this kneeling base makes your hips and core work harder to stay stable than sitting did. Your rotator cuff drives the rotations, deltoids and latissimus dorsi the abduction/adduction, while your obliques and erector spinae hold you upright."] } },
    { name: "Side Twist — Kneeling", level: "Intermediate", page: "114", springs: "1–2", startingPosition: "Kneel on the carriage facing sideways, knees hip-distance apart, femurs vertical, spine and pelvis upright, upper torso rotated slightly toward the pulleys, both hands holding one strap in front of the sternum.", pelvis: "Neutral, square to the side", spine: "Rotation with axial elongation", breathing: "Exhale to rotate the upper torso away from the pulleys (keeping the pelvis square) to move the carriage out\nInhale to return.", targetMuscles: "External oblique on the pulley side and internal oblique on the opposite side (rotation), obliques and erector spinae (torso vertical), hip extensors/adductors/abductors (pelvic stability), scapular stabilizers.", focus: "Manual header: \"Similar to Essential Side Twist Sitting (62).\" Kneeling version of the same rotation pattern — removes the stability of sitting, adding a hip/core stability demand.", modifications: ["Hands further away for a bigger circle, increasing resistance.", "Hold a Fitness Circle® against the rib cage with the strap around the opposite handle, to aid scapular stabilization."] , script: { lines: ["Let's move into Side Twist, Kneeling. Come to kneeling sideways on the carriage, both hands holding one strap in front of your sternum.", "Exhale to rotate your torso away from the pulley, keeping your pelvis square; inhale to return.", "Keep your hips completely still and square as you rotate — the kneeling base makes this a bigger stability challenge than sitting. Feel your obliques on both sides driving the rotation while your hip extensors, adductors and abductors keep your pelvis anchored."] } },
    { name: "Reverse Expansion", level: "Intermediate", page: "115–119", springs: "1–2", startingPosition: "Kneel on the carriage facing the footbar, feet against the shoulder rests, ankles dorsiflexed, femurs vertical, spine and pelvis neutral, arms straight with shoulders extended, hands in straps, per position below.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Exhale to reach/press the arms forward with the action described per position, moving the carriage out\nInhale to return.", targetMuscles: "Pectoralis major and anterior deltoids (positions 1-3), triceps (Salute), biceps (Biceps Curls), rectus abdominis/obliques/erector spinae (torso stability), scapular stabilizers (serratus anterior).", focus: "The reverse-direction cousin of Chest Expansion — reaching and pressing forward from a kneeling base instead of pulling back.\nNOTE: a trained professional must spot throughout, and the exercise should be attempted slowly to avoid falling forward.\nESSENCE bracket confirms [EXERCISES 1-5].", positions: [
      { label: "Straight Forward", detail: "A.K.A. Reaching Forward. Reach the arms forward and up to eye level, palms forward, to move the carriage out; return with control. 4 reps." },
      { label: "Teardrops Outward", detail: "Reach the arms forward and up to eye level, first circling them in toward the midline then directly forward of the shoulders; return circling away from the midline then into the sides. 4 reps." },
      { label: "Teardrops Inward", detail: "Reach the arms forward and up to eye level, first circling them slightly away from the midline then directly in front of the shoulders; return circling slightly toward the midline then by the sides. 4 reps." },
      { label: "Salute", detail: "Hands form a diamond behind the head; press forward and up into the straps extending the elbows, keeping the fingers touching as long as possible, then open the hands to complete the extension; flex to return. 4 reps." },
      { label: "Biceps Curls", detail: "Arms straight and reaching forward, palms front; flex the elbows (humeri staying still) to move the carriage out, extend to return. 10 reps." },
    ], modifications: ["Hands at the forehead instead of behind the head, for less flexible shoulders (Salute).", "Elbows pointing forward, hands apart, to isolate the triceps (Salute)."] , script: { lines: ["Let's move into Reverse Expansion. Come to kneeling on the carriage, facing the footbar, feet against the shoulder rests, arms straight and reaching forward.", "Exhale to reach or press your arms forward with each pattern, moving the carriage out; inhale to return. We'll move through Straight Forward, Teardrops Outward, Teardrops Inward, Salute, then Biceps Curls.", "Move slowly and stay upright — this reaches forward instead of pulling back, so it's easy to tip if you rush. Your pectoralis major and anterior deltoids drive the reach, your triceps or biceps take over in Salute and Biceps Curls, and your rectus abdominis and obliques keep your torso stable."] } },
    { name: "Mermaid (Intermediate)", level: "Intermediate", page: "120–123", springs: "1", startingPosition: "Seated upright, pelvis and spine as neutral as possible, facing square to one side, knees flexed, one leg internally rotated against the shoulder rest, other leg externally rotated with the foot against the opposite knee, heel of one hand on the footbar, other hand on the shoulder rest.", pelvis: "Neutral", spine: "Lateral flexion (with added flexion and rotation in Mermaid with Rotation)", breathing: "Inhale to reach the gesture arm overhead\nExhale to laterally flex toward the footbar while pressing the carriage out by abducting the arm on the footbar\nInhale to return to vertical\nRepeat toward the shoulder rests with arms switched.", targetMuscles: "Internal/external obliques (ipsilateral lateral flexion), obliques and erector spinae (anti-flexion/extension), obliques and multifidus (anti-rotation), scapular stabilizers\nMermaid with Rotation also recruits internal oblique on one side/external on the other for the rotation.", focus: "Manual header: \"Same as Essential (84)\" for the base Mermaid\nAdds a second position, Mermaid with Rotation, unique to Intermediate.\nESSENCE bracket confirms [EXERCISES 1-2].", positions: [
      { label: "Mermaid", detail: "Same as the Essential Mermaid (p.84) — reach the gesture arm overhead, laterally flex toward the footbar while pressing the carriage out with the footbar arm, then repeat toward the shoulder rests." },
      { label: "Mermaid with Rotation", detail: "After laterally flexing toward the footbar and pressing the carriage out, rotate the upper torso to face the footbar and place both hands shoulder-distance apart on the bar; flex and extend the elbows 3 times, then sequentially extend the spine from head to tail (bringing the carriage in) and flex tail to head to return to the flexed, rotated position, before completing the lateral flexion sequence to the other side." },
    ] , script: { lines: ["Let's move into Mermaid. Come to seated, facing sideways, knees bent, one hand on the footbar, other on the shoulder rest.", "Inhale to reach your gesture arm overhead; exhale to laterally flex toward the footbar while pressing the carriage out. We'll add Mermaid with Rotation on the second position, rotating to face the footbar and pressing your hands into it before rolling back up.", "Lengthen your spine before you flex sideways, and keep the movement smooth on both sides — your obliques do the lateral flexing while your erector spinae and multifidus prevent you from flexing forward or rotating."] } },
    { name: "Leg Circles (Intermediate)", level: "Intermediate", page: "124–126", springs: "2", startingPosition: "Supine, pelvis and spine neutral, footbar #1, headrest adjusted for the individual.\nFeet in straps, ankles plantar flexed, toes gently pointed.\nArms long by the sides, palms down.\nSame three leg rotations as the Essential version.", pelvis: "Neutral (imprint if stability can't be maintained, moving toward neutral as the legs hinge toward the torso)", spine: "Neutral", breathing: "Manual header: \"Same as Essential (86).\" Inhale to hinge the legs toward the torso\nExhale to abduct/circle the legs out and press away from the torso to move the carriage out\nReverse — inhale to abduct/circle the legs out and hinge toward the torso\nExhale to adduct and press away.\n10 reps each direction.", targetMuscles: "Transversus abdominis and pelvic floor\nObliques\nHip extensors eccentrically as the legs hinge toward the torso, concentrically as they press away\nHip abductors concentrically to initiate leg opening, eccentrically to control it\nHip adductors concentrically to bring the legs together, isometrically to keep them together as they hinge — same target muscles as the Essential version.", focus: "Re-lists the Essential three-rotation Leg Circles series for Intermediate level.\nManual note: lateral rotation allows larger circles than parallel, medial rotation only comparatively small circles, due to the hip joint's range — don't force a circle bigger than is comfortable at the hip.", positions: [
      { label: "Parallel", detail: "" },
      { label: "Laterally rotated", detail: "" },
      { label: "Medially rotated", detail: "" },
    ], modifications: ["Small/quick circles (all positions)."] , script: { lines: ["Let's move into Leg Circles. Come to supine, feet in the straps, legs extended on the diagonal.", "Inhale to hinge your legs toward your torso; exhale to circle them out and press away, moving the carriage out. We'll work through parallel, turned out, then turned in, ten reps each direction.", "Keep the circle sized to what your hip can comfortably do — turned in will naturally be a smaller circle than turned out. Your hip abductors and adductors drive the circle while your transversus abdominis and obliques keep your pelvis still."] } },
    { name: "Long Spine", level: "Intermediate", page: "128–129", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral, footbar #4, headrest flat, legs straight, adducted and parallel, on the diagonal as low as pelvic stability allows, feet in straps, ankles plantar flexed.\n3 springs if using extension straps, 2 if not.", pelvis: "Neutral (imprint if needed as the legs reach on the diagonal, returning to neutral as the legs hinge toward the torso)", spine: "Full articulated flexion, larger range than Short Spine", breathing: "Inhale to hinge the legs toward the torso, keeping the sacrum on the carriage\nExhale to articulate the spine off the carriage from tail to upper thoracic, reaching the legs to the ceiling\nInhale to abduct/laterally rotate the legs\nExhale to roll the spine back down while the legs stay overhead, hinging the legs away as the sacrum lands\nInhale to adduct/rotate parallel and repeat.\nReverse direction for the second half of the set.", targetMuscles: "Rectus abdominis and obliques (roll off/down), gluteus maximus and hamstrings (hinge and press), scapular stabilizers.", focus: "The most demanding of the spine-articulation-with-straight-legs family — straight legs throughout, unlike the bent-knee Short Spine.\nComplete 3 repetitions in each direction.", faults: ["Bending the knees to cheat the range — keep the legs straight and control the descent with the abdominals, not momentum."], modifications: ["Laterally rotated throughout.", "Parallel throughout."] , script: { lines: ["Let's move into Long Spine. Come to supine, legs straight, adducted and parallel, on the diagonal, feet in the straps.", "Inhale to hinge your legs toward your torso, keeping your sacrum on the carriage; exhale to roll your spine up off the carriage to your upper back, reaching your legs to the ceiling; inhale to rotate your legs out; exhale to roll your spine back down while your legs stay overhead, then hinge them away as your sacrum lands.", "Roll up one bone at a time using your abdominals, not momentum — keep your legs straight throughout, this is the bigger cousin of Short Spine."] } },
    { name: "Knee Stretches (Intermediate)", level: "Intermediate", page: "130–133", springs: "2", startingPosition: "Kneel on the carriage, feet against the shoulder rests, hands holding the footbar, sitting back toward the heels, per position below.", pelvis: "Posterior tilt (Round Back, Knees Off) or neutral (Straight Back, Extended Back)", spine: "Flexion (Round Back, Knees Off), neutral (Straight Back), or extension (Extended Back)", breathing: "Inhale to extend the hips and knees and press the carriage out\nExhale to flex and return.", targetMuscles: "Rectus abdominis and obliques (Round Back, Knees Off, isometric flexion), obliques and erector spinae (Straight Back, Extended Back), hip extensors concentrically on press, hip flexors concentrically on return, quadriceps eccentrically on return (more challenged in Knees Off).", focus: "Same Round Back / Straight Back pair as Essential, extended to four Intermediate positions with two new spinal targets — Extended Back and Knees Off.\nESSENCE bracket confirms [EXERCISES 1-4].", positions: [
      { label: "Round Back", detail: "Same as Essential — spine flexed in a C-curve." },
      { label: "Straight Back", detail: "A.K.A. Flat Back. Same as Essential — pelvis and spine neutral (or slightly imprinted if neutral can't be maintained)." },
      { label: "Extended Back", detail: "Spine extended but stabilized and supported by the abdominals instead of flexed or neutral — a harder isometric demand than Straight Back because the abdominals must control eccentrically." },
      { label: "Knees Off", detail: "Round Back spinal flexion with the knees hovering just above the carriage throughout the press (instead of resting on it) — quadriceps work harder to control the suspended knees." },
    ], modifications: ["Standing — one foot on the floor near the front of the Reformer, other knee flexed on the carriage (Straight Back only).", "Straight Back Knees Off — perform the Knees Off pattern with the spine stabilized in neutral instead of flexion."] , script: { lines: ["Let's move into Knee Stretches. Come to kneeling on the carriage, feet against the shoulder rests, hands on the footbar.", "Inhale to extend your hips and knees, pressing the carriage out; exhale to bend and return. We'll move through Round Back and Straight Back as before, then add Extended Back and Knees Off.", "For Knees Off, keep your knees hovering just above the carriage the whole time — that's what makes your quadriceps work harder."] } },
    { name: "Running (Intermediate)", level: "Intermediate", page: "134–135", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral, balls of the feet on the footbar, ankles plantar flexed, legs parallel and adducted.", pelvis: "Neutral", spine: "Neutral", breathing: "Smooth, continuous, alternating heel lift/press — same as Essential.", targetMuscles: "Gastrocnemius and soleus (alternating heel lift/lower), obliques and multifidus (anti-extension/anti-rotation) — same as Essential.", focus: "Manual header: \"Same as Essential (92).\" The Intermediate write-up documents no movement change from the Essential version\nIt is simply re-listed for review at Intermediate level." , script: { lines: ["Let's move into Running. Same as before — supine, balls of your feet on the bar, alternating your heels lifting and lowering.", "Smooth, continuous breathing throughout.", "Stay light and quick, and keep your pelvis completely stable — your gastrocnemius and soleus do the pulsing while your obliques and multifidus resist any rocking."] } },
    { name: "Hip Lift (Intermediate)", level: "Intermediate", page: "137", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral, heels on the footbar, ankles dorsiflexed, legs parallel and abducted hip-distance apart.", pelvis: "Neutral", spine: "Neutral", breathing: "Exhale to lift the pelvis just off the carriage and stay\nExhale to extend the knees and press the carriage out\nInhale to flex the knees and return\nExhale to lower the pelvis to finish.", targetMuscles: "Rectus abdominis, obliques and erector spinae (torso stability), hamstrings (constant pelvis height), hip extensors and quadriceps — same as Essential.", focus: "Manual header: \"Same as Essential (Pg 95).\" The Intermediate write-up documents no movement change from the Essential version." , script: { lines: ["Let's move into Hip Lift. Come to supine, heels on the footbar, legs parallel, hip-distance apart.", "Exhale to lift your pelvis off the carriage and hold; exhale again to extend your knees and press the carriage out; inhale to bend your knees back in; exhale to lower your pelvis to finish.", "Keep your hips lifted at a constant height the entire time your knees are moving — your hamstrings hold that height while your hip extensors and quadriceps do the pressing."] } },
    { name: "Hip Rolls (Intermediate)", level: "Intermediate", page: "138–139", springs: "2–3", startingPosition: "Supine, pelvis and spine neutral, heels on the footbar, ankles dorsiflexed, legs parallel and abducted hip-distance apart.", pelvis: "Neutral to imprint", spine: "Articulated flexion", breathing: "Exhale to sequentially articulate the spine off the carriage from tail to upper thoracic\nInhale to stay, reaching the knees over the footbar\nExhale to extend the knees and press the carriage out, lowering the pelvis to one line\nInhale to flex the knees and lift the pelvis, returning the carriage\nExhale to articulate the spine back onto the carriage.", targetMuscles: "Rectus abdominis and obliques, gluteus maximus and hamstrings (roll up/down), quadriceps (knee extension) — same as Essential.", focus: "Manual header: \"Same as Essential (pg 96).\" The Intermediate write-up documents no movement change from the Essential version\nThe knee-extension phase already described here is the full exercise, and \"Hip Rolls Prep\" (omitting knee extension) is listed as a modification, not an Intermediate addition.", modifications: ["Hip Rolls Prep — omit the knee extension to develop sequential spinal articulation first."] , script: { lines: ["Let's move into Hip Rolls. Come to supine, heels on the footbar, legs parallel, hip-distance apart.", "Exhale to peel your spine up off the carriage, tail to upper back; inhale to reach your knees over the footbar; exhale to extend your knees and press the carriage out, lowering your hips to one line; inhale to bend your knees and lift your hips, returning the carriage; exhale to roll your spine back down.", "Same pattern as before, now with the knee extension added at the top — keep your hips level as the carriage moves. Your gluteus maximus and hamstrings roll you up and down, your rectus abdominis and obliques control the articulation, and your quadriceps take over for the knee extension."] } },
    { name: "Single Thigh Stretch (Intermediate)", level: "Intermediate", page: "140–141", springs: "2", startingPosition: "Lunge, facing the footbar, one knee flexed on the carriage with the foot against the shoulder rest (hip extended), ball of the other foot on the footbar in line with the sit-bone, pelvis and spine as neutral and square as possible.", pelvis: "Neutral", spine: "Neutral, elongated, extending at the finish", breathing: "Exhale to press back the foot against the shoulder rest and extend the front knee, pressing the carriage out\nInhale to flex the front knee and return.\nAfter the last repetition: inhale to reach the arm on the side of the extended leg toward the ceiling\nExhale to extend the thoracic spine and lift the chest toward the ceiling\nLower to finish.", targetMuscles: "Hip extensors of the back leg (stabilize/increase hip extension), obliques and multifidus (anti-rotation), obliques and erector spinae, scapular stabilizers.", focus: "Manual header: \"Same as Essential (98) except P.4 Extend Arm at the end.\" The only documented Intermediate delta is the finishing reach — after the last rep, both hands come to the top of the front knee, then the arm on the extended-leg side reaches overhead, extending the thoracic spine and lifting the chest, before lowering to finish.", modifications: ["Standing Thigh Stretch — one foot on the floor near the front of the Reformer instead of kneeling, to reduce pressure on the knees."] , script: { lines: ["Let's move into Single Thigh Stretch. Come to a lunge, one knee bent on the carriage with your foot against the shoulder rest, other foot's ball on the footbar.", "Exhale to press your back foot into the shoulder rest and extend your front knee, pressing the carriage out; inhale to bend your front knee and return.", "After your last rep, reach the arm on your extended-leg side overhead and lift your chest, extending through your upper back before you finish. Your back leg's hip extensors stabilize the lunge while your obliques and multifidus guard against rotation."] } },
    { name: "Front Splits", level: "Intermediate", page: "142–143", springs: "1–2", startingPosition: "Lunge, facing the footbar, one knee flexed with the ball of the foot on the footbar in line with the sit-bone, other leg straight with the foot against the shoulder rest (same side as the springs), pelvis square to the front, spine in slight extension.", pelvis: "Neutral, kept at a constant height", spine: "Slight extension, stable", breathing: "Inhale to extend the front knee and press the carriage out\nExhale to flex the front knee and return.", targetMuscles: "Quadriceps of the front leg (press), gluteus maximus/hamstrings of the front leg (prevent sinking), gluteus maximus/hamstrings/quadriceps of the back leg (isometric stability), erector spinae, obliques and multifidus (anti-rotation), scapular stabilizers.", focus: "A standing lunge balance and hip-mobility exercise in the sagittal plane, front-to-back split orientation.\nComplete 5 repetitions on each leg.\nNOTE: a trained professional must spot throughout in case balance is lost.", modifications: ["Hands touching the footbar on either side of the foot, for more support.", "Standing — one foot on the floor near the front of the Reformer instead of kneeling on the carriage."] , script: { lines: ["Let's move into Front Splits. Come to a lunge, facing the footbar, front foot's ball on the bar, back leg straight with the foot against the shoulder rest.", "Inhale to extend your front knee and press the carriage out; exhale to bend your front knee and return.", "Keep your pelvis at one constant height and your torso tall — feel the stretch through the front of your back hip. Your front leg's quadriceps press while both legs' gluteus maximus and hamstrings hold the lunge steady."] } },
    { name: "Back Splits", level: "Intermediate", page: "144–145", springs: "1–2", startingPosition: "Lunge, facing the pulleys, one knee flexed with the ball of the foot in the crease of the headrest directly under the knee, other leg straight, hip extended and laterally rotated with as much of the foot as possible on the footbar, pelvis low and level, spine in extension.", pelvis: "Neutral, kept at one height", spine: "Slight extension, stable", breathing: "Inhale to extend the front knee and press the carriage out\nExhale to flex the front knee (returning the foot directly under the knee) and return the carriage.", targetMuscles: "Quadriceps of the front leg (two-spring version) or hamstrings of the front leg (one-spring version, eccentric on press/concentric on return), gluteus maximus/hamstrings/lateral rotators/quadriceps of the back leg (isometric), erector spinae, obliques and multifidus.", focus: "Completes the standing splits family alongside Front and Side Splits — a reversed orientation to Front Splits.\nComplete 5 repetitions on each leg.\nNOTE: a trained professional must spot throughout in case balance is lost.", modifications: ["Hands holding the shoulder rests, for more support.", "Footbar position #2 — lowering the back leg makes it easier to avoid overextending the lumbar spine."] , script: { lines: ["Let's move into Back Splits. Come to a lunge, facing the pulleys, front knee bent with the foot in the headrest crease, back leg straight and turned out with the foot on the footbar.", "Inhale to extend your front knee and press the carriage out; exhale to bend your front knee and return, foot landing directly under your knee.", "Keep your pelvis level and your spine steady in its slight extension the whole time — your front leg's quadriceps or hamstrings do the pressing, while your back leg's glutes and lateral rotators hold you isometrically."] } },
    { name: "Side Splits (Intermediate)", level: "Intermediate", page: "146–153", springs: "0.5–2", startingPosition: "Standing on the Reformer facing sideways, one foot on the wooden platform, one foot on the edge of the carriage, spine and pelvis neutral, arms straight out to the sides, per position below.", pelvis: "Neutral, level", spine: "Neutral, elongated", breathing: "Exhale to press the carriage out with the leg action described per position\nInhale to return.", targetMuscles: "Hip abductors (Abduction, heavier springs), hip adductors (Adduction, lighter springs), quadriceps (Plié Out/In, Carriage/Platform Leg Pressing, Skating), obliques and erector spinae (torso stability) throughout.", focus: "Manual header: \"Same as Essential (100/101)\" for Abduction and Adduction\nAdds five further Intermediate-only positions built around a knee-flexed plié base.\nESSENCE bracket confirms [EXERCISES 3-7] cover the plié family.", positions: [
      { label: "Abduction", detail: "Same as Essential — press both legs evenly away from the midline to move the carriage out, straight knees. Heavier springs suit this direction." },
      { label: "Adduction", detail: "Same as Essential — control the carriage as the legs open, then draw the legs evenly toward the midline to return, straight knees. Lighter springs suit this direction." },
      { label: "Plié Out", detail: "Flex both knees (plié) with the carriage still, then abduct the legs evenly, maintaining the same knee flexion, to press the carriage out; extend the knees, then adduct to return." },
      { label: "Plié In", detail: "Reverse of Plié Out — abduct the straight legs to press the carriage out first, then flex the knees; adduct with knees flexed to bring the carriage in, then extend the knees." },
      { label: "Carriage Leg Pressing", detail: "Knees flexed throughout; keep more weight on the platform foot and extend the knee of the carriage leg to press the carriage out, flex to return." },
      { label: "Platform Leg Pressing", detail: "Knees flexed throughout; keep more weight on the carriage foot and extend the knee of the platform leg (pelvis moves with this leg) to press the carriage out, flex to return." },
      { label: "Skating", detail: "Knees flexed throughout; extend the platform leg's knee shifting the pelvis and weight onto the carriage leg, flex to bring weight central, then shift to the platform leg by extending the carriage leg's knee and flexing to return — one smooth, flowing skating motion. 5 reps." },
    ], modifications: ["Legs laterally rotated (Adduction) — engages lateral rotators and hamstrings.", "Hands on the hips (all positions) — reduces upper trapezius overwork, gives a tactile pelvic reference.", "Adduction / Abduction emphasis via lighter or heavier spring tension, parallel or laterally rotated (positions 3-7)."] , script: { lines: ["Let's move into Side Splits. Come to standing, one foot on the platform, one on the carriage, arms out to the sides.", "Exhale to press the carriage out with each leg action; inhale to return. We'll repeat Abduction and Adduction from before, then add the plié family — Plié Out, Plié In, Carriage Leg Pressing, Platform Leg Pressing, and finish with Skating.", "Keep your pelvis level throughout, even as the plié positions add knee bend into the mix — your hip abductors and adductors drive the legs, your quadriceps control the plié, and your obliques and erector spinae keep your torso from tipping."] } },
    { name: "Star Prep", level: "Intermediate", page: "155", springs: "1–2", startingPosition: "Kneel on the carriage facing sideways, leaning on a diagonal toward the footbar, propped on the underneath arm with the heel of the hand on the footbar, top knee against the front shoulder rest, bottom knee on the carriage, one line from knees to head, top arm resting along the side.", pelvis: "Neutral", spine: "Lateral stability, one long line from knees to head", breathing: "Inhale to abduct the supporting arm (pressing the carriage out) while simultaneously abducting the top arm\nExhale to adduct the supporting arm (pulling the carriage in) while lowering the top arm.", targetMuscles: "Obliques and erector spinae (spine neutral), underneath obliques and hip abductors (prevent the pelvis sinking), gluteus maximus/hamstrings/abdominals (pelvis stability), scapular stabilizers (serratus anterior) and deltoid/supraspinatus (shoulder abduction) of the supporting side, latissimus dorsi and teres major (control adduction), obliques and multifidus (anti-rotation).", focus: "A challenging full-body lateral stability exercise building toward a full side-plank \"star\" shape — one of the harder Intermediate finishers.\nComplete 5 repetitions on each side.\nNOTE: a trained professional must spot throughout in case balance is lost." , script: { lines: ["Let's move into Star Prep. Come to kneeling sideways on the carriage, leaning on a diagonal, propped on your underneath arm, top knee against the front shoulder rest.", "Inhale to press the carriage out with your supporting arm while lifting your top arm; exhale to pull the carriage back in as your top arm lowers.", "Keep one long line from your knees to your head — don't let your hips sink toward the carriage. Your underneath obliques and hip abductors prevent the sink, your deltoid and supraspinatus drive the arm abduction, and your latissimus dorsi controls the return."] } },
  ],
  advanced: [],
};
